        private boolean isReviewedPrismariCommandShatterMode(SpellAbility ability, SpellAbility root) {
            return isReviewedPrismariCommandShatterBody(ability, root)
                    && ability.getSubAbility() == null;
        }

        private int reviewedPrismariCommandModeIndex(SpellAbility ability, SpellAbility root) {
            if (isReviewedPrismariCommandShockBody(ability, root)) return 0;
            if (isReviewedPrismariCommandLootBody(ability, root)) return 1;
            if (isReviewedPrismariCommandTreasureBody(ability, root)) return 2;
            if (isReviewedPrismariCommandShatterBody(ability, root)) return 3;
            return -1;
        }

        private SpellAbility reviewedPrismariCommandNextMode(SpellAbility ability, int index) {
            SpellAbility next = ability.getSubAbility();
            return index == 1 && next != null ? next.getSubAbility() : next;
        }

        private boolean isReviewedPrismariCommandActiveComposition(SpellAbility root) {
            if (!isReviewedPrismariCommandRoot(root)) return false;
            SpellAbility first = root.getSubAbility();
            int firstIndex = first == null ? -1 : reviewedPrismariCommandModeIndex(first, root);
            SpellAbility second = firstIndex < 0 ? null : reviewedPrismariCommandNextMode(first, firstIndex);
            int secondIndex = second == null ? -1 : reviewedPrismariCommandModeIndex(second, root);
            return first != null
                    && second != null
                    && first.getParent() == root
                    && firstIndex >= 0
                    && secondIndex > firstIndex
                    && "1".equals(first.getSVar("CharmOrder"))
                    && "2".equals(second.getSVar("CharmOrder"))
                    && reviewedPrismariCommandNextMode(second, secondIndex) == null;
        }

        private boolean isReviewedPrismariCommandActiveMode(
                SpellAbility ability, SpellAbility root, int expectedIndex) {
            if (!isReviewedPrismariCommandActiveComposition(root)
                    || reviewedPrismariCommandModeIndex(ability, root) != expectedIndex) {
                return false;
            }
            SpellAbility first = root.getSubAbility();
            int firstIndex = reviewedPrismariCommandModeIndex(first, root);
            SpellAbility second = reviewedPrismariCommandNextMode(first, firstIndex);
            return ability == first || ability == second;
        }

        private boolean isReviewedPrismariCommandTarget(SpellAbility ability) {
            SpellAbility root = ability.getRootAbility();
            return root != ability
                    && isReviewedPrismariCommandActiveComposition(root)
                    && isReviewedPrismariCommandActiveMode(
                            ability, root, reviewedPrismariCommandModeIndex(ability, root));
        }

        private boolean isReviewedBlessedAllianceRoot(SpellAbility ability) {
            Card source = ability.getHostCard();
            List<AbilitySub> modes = ability.getAdditionalAbilityList("Choices");
            Cost cost = ability.getPayCosts();
            List<CostPart> parts = cost == null ? List.of() : cost.getCostParts();
            Collection<KeywordInterface> escalate = source == null
                    ? List.of()
                    : source.getKeywords(Keyword.ESCALATE);
            return source != null
                    && "Blessed Alliance".equals(source.getName())
                    && ability.getApi() == ApiType.Charm
                    && ability.isSpell()
                    && !ability.isTrigger()
                    && !ability.isActivatedAbility()
                    && ability.getParent() == null
                    && ability.getRootAbility() == ability
                    && "1".equals(ability.getParam("MinCharmNum"))
                    && "3".equals(ability.getParam("CharmNum"))
                    && "DBGainLife,DBUntap,DBSacrifice".equals(ability.getParam("Choices"))
                    && modes.size() == 3
                    && parts.size() == 1
                    && parts.get(0).getClass() == CostPartMana.class
                    && "{1}{W}".equals(((CostPartMana) parts.get(0)).getMana().getSimpleString())
                    && escalate.size() == 1
                    && "Escalate:2".equals(escalate.iterator().next().getOriginal())
                    && isReviewedBlessedAllianceGainMode(modes.get(0), ability)
                    && isReviewedBlessedAllianceUntapMode(modes.get(1), ability)
                    && isReviewedBlessedAllianceSacrificeMode(modes.get(2), ability)
                    && modes.get(0).getSubAbility() == null
                    && modes.get(1).getSubAbility() == null
                    && modes.get(2).getSubAbility() == null;
        }

        private boolean isReviewedBlessedAllianceModeRoot(SpellAbility mode, SpellAbility root) {
            return root != null
                    && mode.getHostCard() == root.getHostCard()
                    && mode.getParent() != null
                    && mode.getParent().getRootAbility() == root
                    && mode.getRootAbility() == root
                    && !mode.isSpell()
                    && !mode.isTrigger()
                    && !mode.isActivatedAbility()
                    && !mode.hasParam("TargetingPlayer");
        }

        private boolean isReviewedBlessedAllianceTargetBlock(
                SpellAbility ability, SpellAbility root, ApiType api, int minimum, int maximum) {
            TargetRestrictions restrictions = ability.getTargetRestrictions();
            return isReviewedBlessedAllianceModeRoot(ability, root)
                    && ability.getApi() == api
                    && ability.usesTargeting()
                    && ability.getMinTargets() == minimum
                    && ability.getMaxTargets() == maximum
                    && !ability.isDividedAsYouChoose()
                    && restrictions != null
                    && !restrictions.isRandomTarget()
                    && restrictions.getZone().size() == 1
                    && restrictions.getZone().contains(ZoneType.Battlefield);
        }

        private boolean isReviewedBlessedAllianceGainMode(SpellAbility ability, SpellAbility root) {
            return isReviewedBlessedAllianceTargetBlock(ability, root, ApiType.GainLife, 1, 1)
                    && "Player".equals(ability.getParam("ValidTgts"))
                    && "Select target player (to gain 4 life)".equals(ability.getParam("TgtPrompt"))
                    && "4".equals(ability.getParam("LifeAmount"));
        }

        private boolean isReviewedBlessedAllianceUntapMode(SpellAbility ability, SpellAbility root) {
            return isReviewedBlessedAllianceTargetBlock(ability, root, ApiType.Untap, 0, 2)
                    && "Creature".equals(ability.getParam("ValidTgts"));
        }

        private boolean isReviewedBlessedAllianceSacrificeMode(SpellAbility ability, SpellAbility root) {
            return isReviewedBlessedAllianceTargetBlock(ability, root, ApiType.Sacrifice, 1, 1)
                    && "Opponent".equals(ability.getParam("ValidTgts"))
                    && "Select target player (to sacrifice an attacking creature)"
                            .equals(ability.getParam("TgtPrompt"))
                    && "Creature.attacking".equals(ability.getParam("SacValid"))
                    && "Creature".equals(ability.getParam("SacMessage"));
        }

        private int reviewedBlessedAllianceModeIndex(SpellAbility ability, SpellAbility root) {
            if (isReviewedBlessedAllianceGainMode(ability, root)) return 0;
            if (isReviewedBlessedAllianceUntapMode(ability, root)) return 1;
            if (isReviewedBlessedAllianceSacrificeMode(ability, root)) return 2;
            return -1;
        }

        private boolean isReviewedBlessedAllianceCharm(
                SpellAbility ability, List<AbilitySub> possible, int min, int num, boolean allowRepeat) {
            if (!isReviewedBlessedAllianceRoot(ability)
                    || min != 1
                    || num != possible.size()
                    || num < 1
                    || num > 3
                    || allowRepeat) {
                return false;
            }
            List<AbilitySub> modes = ability.getAdditionalAbilityList("Choices");
            int prior = -1;
            for (AbilitySub candidate : possible) {
                int index = modes.indexOf(candidate);
                if (index <= prior) return false;
                prior = index;
            }
            return true;
        }

        private boolean isReviewedBlessedAllianceActiveComposition(SpellAbility root) {
            if (!isReviewedBlessedAllianceRoot(root)) return false;
            SpellAbility mode = root.getSubAbility();
            int count = 0;
            int prior = -1;
            while (mode != null) {
                int index = reviewedBlessedAllianceModeIndex(mode, root);
                count++;
                if (index <= prior
                        || count > 3
                        || !Integer.toString(count).equals(mode.getSVar("CharmOrder"))) {
                    return false;
                }
                prior = index;
                mode = mode.getSubAbility();
            }
            return count >= 1;
        }

        private boolean isReviewedBlessedAllianceActiveMode(SpellAbility ability) {
            SpellAbility root = ability.getRootAbility();
            if (root == ability || !isReviewedBlessedAllianceActiveComposition(root)) return false;
            for (SpellAbility mode = root.getSubAbility(); mode != null; mode = mode.getSubAbility()) {
                if (mode == ability) return true;
            }
            return false;
        }

        private boolean isReviewedBlessedAllianceTarget(SpellAbility ability) {
            return isReviewedBlessedAllianceActiveMode(ability)
                    && (isReviewedBlessedAllianceGainMode(ability, ability.getRootAbility())
                            || isReviewedBlessedAllianceUntapMode(ability, ability.getRootAbility())
                            || isReviewedBlessedAllianceSacrificeMode(ability, ability.getRootAbility()));
        }

        private boolean isReviewedMysticConfluenceCharm(
                SpellAbility ability, List<AbilitySub> possible, int min, int num, boolean allowRepeat) {
            Card source = ability.getHostCard();
            List<AbilitySub> modes = ability.getAdditionalAbilityList("Choices");
            if (source == null
                    || !"Mystic Confluence".equals(source.getName())
                    || ability.getApi() != ApiType.Charm
                    || !ability.isSpell()
                    || ability.isTrigger()
                    || ability.isActivatedAbility()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || !"DBCounter,DBReturn,DBDraw".equals(ability.getParam("Choices"))
                    || min != 3
                    || num != 3
                    || !allowRepeat
                    || modes.size() != 3
                    || !isReviewedMysticConfluenceCounterMode(modes.get(0), ability)
                    || !isReviewedMysticConfluenceReturnMode(modes.get(1), ability)
                    || !isReviewedMysticConfluenceDrawMode(modes.get(2), ability)
                    || modes.get(0).getSubAbility() != null
                    || modes.get(1).getSubAbility() != null
                    || modes.get(2).getSubAbility() != null
                    || possible.isEmpty()
                    || possible.size() > modes.size()) {
                return false;
            }
            int prior = -1;
            for (AbilitySub candidate : possible) {
                int index = modes.indexOf(candidate);
                if (index <= prior) return false;
                prior = index;
            }
            return true;
        }

