        /** Exact variable target route for Agadeem's Awakening, including a legal zero-target cast. */
        boolean chooseAgadeemsAwakeningTargets(Player player, SpellAbility ability) {
            if (!isReviewedAgadeemsAwakeningTarget(ability) || !ability.getTargets().isEmpty()) {
                throw new IllegalStateException(
                        "Forge reached multiple targeting outside reviewed-agadeems-awakening-v1");
            }
            TargetRestrictions restrictions = ability.getTargetRestrictions();
            Card source = ability.getHostCard();
            int maximum = ability.getMaxTargets();
            int xPaid = ability.getXManaCostPaid();
            if (maximum < 0) {
                throw new IllegalStateException("Forge calculated a negative Agadeem target maximum");
            }
            List<GameEntity> remaining = new ArrayList<>();
            for (GameEntity candidate : restrictions.getAllCandidates(ability)) {
                if (!(candidate instanceof Card card)
                        || !card.isInZone(ZoneType.Graveyard)
                        || !card.isCreature()
                        || card.getOwner() != player
                        || card.getCMC() > xPaid
                        || !ability.canTarget(candidate)
                        || !meetsMustTargetRestriction(ability, candidate)) {
                    throw new IllegalStateException(
                            "Forge offered a target outside the exact Agadeem graveyard profile");
                }
                remaining.add(candidate);
            }
            while (ability.getTargets().size() < maximum) {
                List<Choice> choices = new ArrayList<>();
                for (GameEntity candidate : remaining) {
                    if (!ability.canTarget(candidate)) continue;
                    Card card = (Card) candidate;
                    String id = "target-card-" + card.getId();
                    choices.add(new Choice(
                            id,
                            "Target " + card.getName() + " [" + id + "]",
                            card,
                            List.of(new ChoiceTarget("forge-card-" + card.getId(), card.getName()))));
                }
                choices.add(new Choice(
                        "agadeem-targets-done",
                        "Return " + ability.getTargets().size() + " creature"
                                + (ability.getTargets().size() == 1 ? "" : "s"),
                        null));
                if (ability.getTargets().isEmpty()) {
                    choices.add(new Choice(
                            "target-cancel",
                            "Cancel casting Agadeem's Awakening",
                            null));
                }
                Choice selected = awaitChoice(
                        player,
                        "target-selection",
                        restrictions.getVTSelection().replace("CARDNAME", source.getName())
                                + " (" + ability.getTargets().size() + " of " + maximum + " chosen)",
                        choices);
                if ("agadeem-targets-done".equals(selected.id)) return true;
                if ("target-cancel".equals(selected.id)) return false;
                if (!(selected.value instanceof GameEntity target)
                        || !remaining.contains(target)
                        || !ability.canTarget(target)
                        || !ability.getTargets().add(target)) {
                    throw new IllegalStateException("selected Agadeem target disappeared");
                }
                remaining.remove(target);
            }
            return true;
        }

