        private boolean isReviewedBloodchiefsThirstTarget(SpellAbility ability) {
            Card source = ability.getHostCard();
            SpellAbility root = ability.getRootAbility();
            if (source == null
                    || !"Bloodchief's Thirst".equals(source.getName())
                    || root == null
                    || root.getApi() != ApiType.Destroy
                    || !root.isSpell()
                    || root.isTrigger()
                    || root.isActivatedAbility()
                    || root.getParent() != null
                    || root.getRootAbility() != root
                    || root.getSubAbility() == null
                    || root.getSubAbility().getApi() != ApiType.Destroy
                    || root.getSubAbility().getParent() != root
                    || root.getSubAbility().getSubAbility() != null) {
                return false;
            }
            boolean ordinaryBlock = ability == root
                    && "Creature.cmcLE2,Planeswalker.cmcLE2".equals(ability.getParam("ValidTgts"));
            boolean kickedBlock = ability == root.getSubAbility()
                    && "Creature,Planeswalker".equals(ability.getParam("ValidTgts"));
            TargetRestrictions restrictions = ability.getTargetRestrictions();
            boolean exactExclusiveCardinality =
                    (root.getMinTargets() == 1
                                    && root.getMaxTargets() == 1
                                    && root.getSubAbility().getMinTargets() == 0
                                    && root.getSubAbility().getMaxTargets() == 0)
                            || (root.getMinTargets() == 0
                                    && root.getMaxTargets() == 0
                                    && root.getSubAbility().getMinTargets() == 1
                                    && root.getSubAbility().getMaxTargets() == 1);
            return (ordinaryBlock || kickedBlock)
                    && exactExclusiveCardinality
                    && !ability.isDividedAsYouChoose()
                    && !restrictions.isRandomTarget()
                    && restrictions.getZone().size() == 1
                    && restrictions.getZone().contains(ZoneType.Battlefield)
                    && !ability.hasParam("TargetingPlayer");
        }

