        /** The two exact look-three spells whose order is followed by an optional shuffle. */
        private boolean isReviewedRearrangeTopOfLibraryAbility(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            SpellAbility root = ability.getRootAbility();
            if (source == null
                    || root == null
                    || ability != root
                    || root.getApi() != ApiType.RearrangeTopOfLibrary
                    || !root.isSpell()
                    || root.isTrigger()
                    || root.isActivatedAbility()
                    || root.getParent() != null
                    || root.getRootAbility() != root
                    || !"3".equals(root.getParam("NumCards"))
                    || !root.hasParam("MayShuffle")
                    || root.getSubAbility() == null) {
                return false;
            }
            if ("Ponder".equals(source.getName())) {
                return !root.usesTargeting()
                        && "You".equals(root.getParam("Defined"))
                        && root.getSubAbility().getApi() == ApiType.Draw
                        && "You".equals(root.getSubAbility().getParam("Defined"))
                        && "1".equals(root.getSubAbility().getParam("NumCards"));
            }
            if ("Portent".equals(source.getName())) {
                return root.usesTargeting()
                        && root.getMinTargets() == 1
                        && root.getMaxTargets() == 1
                        && "Player".equals(root.getParam("ValidTgts"))
                        && root.getSubAbility().getApi() == ApiType.DelayedTrigger
                        && "True".equals(root.getSubAbility().getParam("NextTurn"))
                        && "Phase".equals(root.getSubAbility().getParam("Mode"))
                        && "Upkeep".equals(root.getSubAbility().getParam("Phase"));
            }
            return false;
        }

        /** Exact destination represented by each step of Expressive Iteration's Dig chain. */
        private static String isReviewedExpressiveIterationChoice(SpellAbility ability) {
            if (ability == null) return null;
            Card source = ability.getHostCard();
            SpellAbility root = ability.getRootAbility();
            SpellAbility toBottom = root == null ? null : root.getSubAbility();
            SpellAbility toExile = toBottom == null ? null : toBottom.getSubAbility();
            SpellAbility effect = toExile == null ? null : toExile.getSubAbility();
            SpellAbility cleanup = effect == null ? null : effect.getSubAbility();
            if (source == null
                    || !"Expressive Iteration".equals(source.getName())
                    || root == null
                    || root.getApi() != ApiType.Dig
                    || !root.isSpell()
                    || root.isTrigger()
                    || root.isActivatedAbility()
                    || root.getParent() != null
                    || root.getRootAbility() != root
                    || root.usesTargeting()
                    || !"3".equals(root.getParam("DigNum"))
                    || !"1".equals(root.getParam("ChangeNum"))
                    || !"True".equals(root.getParam("NoReveal"))
                    || !"0".equals(root.getParam("LibraryPosition2"))
                    || !"True".equals(root.getParam("SkipReorder"))
                    || !"True".equals(root.getParam("NoLooking"))
                    || toBottom == null
                    || toBottom.getApi() != ApiType.Dig
                    || toBottom.getParent() != root
                    || !"2".equals(toBottom.getParam("DigNum"))
                    || !"1".equals(toBottom.getParam("ChangeNum"))
                    || !"True".equals(toBottom.getParam("NoReveal"))
                    || !"Library".equals(toBottom.getParam("DestinationZone"))
                    || !"0".equals(toBottom.getParam("LibraryPosition2"))
                    || toExile == null
                    || toExile.getApi() != ApiType.Dig
                    || toExile.getParent() != toBottom
                    || !"1".equals(toExile.getParam("DigNum"))
                    || !"All".equals(toExile.getParam("ChangeNum"))
                    || !"True".equals(toExile.getParam("NoReveal"))
                    || !"Exile".equals(toExile.getParam("DestinationZone"))
                    || !"True".equals(toExile.getParam("SkipReorder"))
                    || !"True".equals(toExile.getParam("RememberChanged"))
                    || !"True".equals(toExile.getParam("NoLooking"))
                    || effect == null
                    || effect.getApi() != ApiType.Effect
                    || effect.getParent() != toExile
                    || cleanup == null
                    || cleanup.getApi() != ApiType.Cleanup
                    || cleanup.getParent() != effect
                    || cleanup.getSubAbility() != null) {
                return null;
            }
            if (ability == root) return "hand";
            if (ability == toBottom) return "library-bottom";
            if (ability == toExile) return "exile-playable";
            return null;
        }

        <T extends GameEntity> List<T> chooseExpressiveIterationCard(
                Player player,
                FCollectionView<T> options,
                int minimum,
                int maximum,
                DelayedReveal delayedReveal,
                SpellAbility ability,
                Player targetedPlayer,
                Map<String, Object> params) {
            String destination = isReviewedExpressiveIterationChoice(ability);
            boolean revealValid = destination != null
                    && (destination.equals("hand")
                            ? delayedReveal == null
                            : delayedReveal != null
                                    && delayedReveal.getZone().size() == 1
                                    && delayedReveal.getZone().contains(ZoneType.Library));
            boolean candidatesValid = !options.isEmpty() && options.size() <= 3;
            for (T option : options) {
                if (!(option instanceof Card card)
                        || card.getOwner() != player
                        || card.getZone() == null
                        || card.getZone().getZoneType() != ZoneType.Library) {
                    candidatesValid = false;
                }
            }
            if (destination == null
                    || ability.getActivatingPlayer() != player
                    || minimum != 1
                    || maximum != 1
                    || !revealValid
                    || (targetedPlayer != null && targetedPlayer != player)
                    || (params != null && !params.isEmpty())
                    || !candidatesValid) {
                throw new IllegalStateException(
                        "outside reviewed-expressive-iteration-choice-v1"
                                + " (destination=" + destination
                                + ", minimum=" + minimum
                                + ", maximum=" + maximum
                                + ", options=" + options.size()
                                + ", delayedReveal=" + delayedReveal
                                + ", revealValid=" + revealValid
                                + ", targetedPlayer=" + targetedPlayer
                                + ", player=" + player
                                + ", params=" + params
                                + ", candidatesValid=" + candidatesValid + ")");
            }
            String decisionKind = switch (destination) {
                case "hand" -> "entity-selection-to-hand";
                case "library-bottom" -> "entity-selection-to-library-bottom";
                case "exile-playable" -> "entity-selection-to-exile-playable";
                default -> throw new IllegalStateException(
                        "reviewed Expressive Iteration destination has no decision kind: " + destination);
            };
            return chooseEntities(
                    player,
                    decisionKind,
                    about(ability.getHostCard(), "Choose a card for " + destination),
                    options,
                    minimum,
                    maximum);
        }

        private boolean isReviewedDoomsdayRearrange(SpellAbility ability) {
            if (!supportsScopedContracts || ability == null) return false;
            Card source = ability.getHostCard();
            SpellAbility root = ability.getRootAbility();
            return source != null
                    && "Doomsday".equals(source.getName())
                    && root != null
                    && root != ability
                    && root.getApi() == ApiType.ChangeZone
                    && root.isSpell()
                    && !root.isTrigger()
                    && !root.isActivatedAbility()
                    && root.getParent() == null
                    && root.getRootAbility() == root
                    && ability.getApi() == ApiType.RearrangeTopOfLibrary
                    && ability.getParent() != null
                    && ability.getSubAbility() != null
                    && "You".equals(ability.getParam("Defined"))
                    && "X".equals(ability.getParam("NumCards"))
                    && "Count$ValidLibrary Card.YouOwn".equals(source.getSVar("X"))
                    && "DB$ RearrangeTopOfLibrary | Defined$ You | NumCards$ X | SubAbility$ DBLoseLife"
                            .equals(source.getSVar("DBDig"));
        }

        /** The exact payment profile allowed to reach the Convoke distribution callback. */
        private boolean isReviewedConvokeAbility(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            SpellAbility root = ability.getRootAbility();
            if (source == null
                    || root == null
                    || ability != root
                    || !root.isSpell()
                    || root.isTrigger()
                    || root.isActivatedAbility()
                    || root.getParent() != null
                    || root.getRootAbility() != root
                    || !source.hasKeyword(Keyword.CONVOKE)) {
                return false;
            }
            if ("Hogaak, Arisen Necropolis".equals(source.getName())) {
                return source.isCreature()
                        && source.hasKeyword(Keyword.DELVE)
                        && root.getApi() == ApiType.PermanentCreature
                        && !root.usesTargeting()
                        && "None".equals(root.getParam("ManaRestriction"));
            }
            // The payment callback is name-agnostic (chooseConvokePayments walks Forge's own
            // shard priority), so any plain Convoke spell reaches it. Convoke combined with
            // another cost-altering keyword is a different shape and stays refused, except
            // Hogaak's pinned Delve pairing above.
            return !source.hasKeyword(Keyword.DELVE)
                    && !source.hasKeyword(Keyword.IMPROVISE)
                    && !source.hasKeyword(Keyword.ASSIST);
        }

        /** The exact payment profile allowed to reach the Improvise distribution callback. */
        private boolean isReviewedImproviseAbility(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            SpellAbility root = ability.getRootAbility();
            if (source == null
                    || root == null
                    || ability != root
                    || !root.isSpell()
                    || root.isTrigger()
                    || root.isActivatedAbility()
                    || root.getParent() != null
                    || root.getRootAbility() != root
                    || !source.hasKeyword(Keyword.IMPROVISE)) {
                return false;
            }
            // Improvise always reduces the spell's generic cost by {1} per tapped artifact
            // (InputSelectCardsForConvokeOrImprovise.onCardSelected pays ManaCostShard.COLORLESS
            // unconditionally on the artifacts branch, unlike Convoke's colored-shard choice), so
            // the payment callback needs no color logic. Convoke combined with Improvise is
            // Forge's "Waterbend" shape (artifacts=true, creatures=true) and stays refused, as does
            // any other cost-altering keyword pairing.
            return !source.hasKeyword(Keyword.CONVOKE)
                    && !source.hasKeyword(Keyword.DELVE)
                    && !source.hasKeyword(Keyword.ASSIST);
        }

        /** What a refused Convoke callback looked like, so the failure names the card and the shape. */
        private static String describeConvokeShape(
                SpellAbility ability, boolean artifacts, boolean creatures, Integer maxReduction) {
            Card source = ability == null ? null : ability.getHostCard();
            SpellAbility root = ability == null ? null : ability.getRootAbility();
            return "card=" + (source == null ? null : source.getName())
                    + ", api=" + (ability == null ? null : ability.getApi())
                    + ", isRoot=" + (ability != null && ability == root)
                    + ", isSpell=" + (ability != null && ability.isSpell())
                    + ", isTrigger=" + (ability != null && ability.isTrigger())
                    + ", isActivated=" + (ability != null && ability.isActivatedAbility())
                    + ", delve=" + (source != null && source.hasKeyword(Keyword.DELVE))
                    + ", improvise=" + (source != null && source.hasKeyword(Keyword.IMPROVISE))
                    + ", assist=" + (source != null && source.hasKeyword(Keyword.ASSIST))
                    + ", artifacts=" + artifacts
                    + ", creatures=" + creatures
                    + ", maxReduction=" + maxReduction;
        }

        /**
         * A Convoke payment is a distribution, not an unordered selection.
         *
         * Forge owns which shard a chosen creature can pay. The wire states only
         * the next creature (or Done), then this method applies Forge's own
         * {@link ManaCostBeingPaid#payManaViaConvoke(byte)} priority to the
         * remaining cost. Recomputing the choices after every pick prevents the
         * bridge from ever offering a creature whose colors can no longer pay a
         * shard.
         */
        Map<Card, ManaCostShard> chooseConvokePayments(
                Player player, SpellAbility ability, ManaCost cost, CardCollectionView untapped) {
            ManaCostBeingPaid remaining = new ManaCostBeingPaid(cost);
            List<Card> available = new ArrayList<>();
            for (Card card : untapped) available.add(card);
            int ceiling = Math.min(cost.getCMC(), available.size());
            Map<Card, ManaCostShard> payments = new LinkedHashMap<>();
            while (payments.size() < ceiling) {
                List<Choice> choices = new ArrayList<>();
                for (Card card : available) {
                    if (!canPayViaConvoke(remaining, card)) continue;
                    String id = "convoke-payment-" + entityId(card);
                    choices.add(new Choice(
                            id,
                            "Tap " + card.getName() + " for Convoke [" + id + "]",
                            card,
                            List.of(entityTarget(card))));
                }
                if (choices.isEmpty()) break;
                choices.add(new Choice(
                        "convoke-payment-done",
                        payments.isEmpty() ? "Pay no mana with Convoke" : "Done choosing Convoke payments",
                        DoneChoosing.INSTANCE));
                Object value = awaitChoice(
                                player,
                                "convoke-payment",
                                about(ability.getHostCard(), "Choose creatures to tap for Convoke. Remaining mana cost is "
                                        + remaining),
                                choices)
                        .value;
                if (value == DoneChoosing.INSTANCE) break;
                if (!(value instanceof Card card) || !available.remove(card)) {
                    throw new IllegalStateException("selected Convoke creature disappeared");
                }
                byte chosenColor = convokeColor(player, card, remaining);
                ManaCostShard shard = remaining.payManaViaConvoke(chosenColor);
                if (shard == null) throw new IllegalStateException("selected Convoke creature no longer pays a shard");
                payments.put(card, shard);
            }
            return payments;
        }

        private boolean canPayViaConvoke(ManaCostBeingPaid remaining, Card card) {
            ColorSet colors = card.getColor();
            if (colors.countColors() == 0) {
                return new ManaCostBeingPaid(remaining.toManaCost()).payManaViaConvoke(MagicColor.COLORLESS)
                        != null;
            }
            for (MagicColor.Color color : colors.getOrderedColors()) {
                if (new ManaCostBeingPaid(remaining.toManaCost()).payManaViaConvoke(color.getColorMask()) != null) {
                    return true;
                }
            }
            return false;
        }

        /**
         * An Improvise payment taps artifacts one at a time, same shape as
         * {@link #chooseConvokePayments}, except every tapped artifact pays the
         * colorless shard unconditionally (no color choice: an artifact's own
         * color, if it has one, is irrelevant to Improvise).
         */
        Map<Card, ManaCostShard> chooseImprovisePayments(
                Player player, SpellAbility ability, ManaCost cost, CardCollectionView untapped) {
            ManaCostBeingPaid remaining = new ManaCostBeingPaid(cost);
            List<Card> available = new ArrayList<>();
            for (Card card : untapped) available.add(card);
            int ceiling = Math.min(cost.getCMC(), available.size());
            Map<Card, ManaCostShard> payments = new LinkedHashMap<>();
            while (payments.size() < ceiling) {
                List<Choice> choices = new ArrayList<>();
                for (Card card : available) {
                    if (!canPayViaImprovise(remaining)) continue;
                    String id = "improvise-payment-" + entityId(card);
                    choices.add(new Choice(
                            id,
                            "Tap " + card.getName() + " for Improvise [" + id + "]",
                            card,
                            List.of(entityTarget(card))));
                }
                if (choices.isEmpty()) break;
                choices.add(new Choice(
                        "improvise-payment-done",
                        payments.isEmpty() ? "Pay no cost with Improvise" : "Done choosing Improvise payments",
                        DoneChoosing.INSTANCE));
                Object value = awaitChoice(
                                player,
                                "improvise-payment",
                                about(ability.getHostCard(), "Choose artifacts to tap for Improvise. Remaining mana cost is "
                                        + remaining),
                                choices)
                        .value;
                if (value == DoneChoosing.INSTANCE) break;
                if (!(value instanceof Card card) || !available.remove(card)) {
                    throw new IllegalStateException("selected Improvise artifact disappeared");
                }
                ManaCostShard shard = remaining.payManaViaConvoke(MagicColor.COLORLESS);
                if (shard == null) throw new IllegalStateException("selected Improvise artifact no longer pays a shard");
                payments.put(card, shard);
            }
            return payments;
        }

        private boolean canPayViaImprovise(ManaCostBeingPaid remaining) {
            return new ManaCostBeingPaid(remaining.toManaCost()).payManaViaConvoke(MagicColor.COLORLESS) != null;
        }

        private byte convokeColor(Player player, Card card, ManaCostBeingPaid remaining) {
            ColorSet colors = card.getColor();
            if (colors.isMulticolor()) {
                colors = ColorSet.fromMask(colors.getColor() & remaining.getUnpaidColors());
            }
            if (colors.isMulticolor()) {
                return chooseColorMask(player, "Convoke " + card + " for which color?", card, colors, false);
            }
            return colors.getColor();
        }

