        private boolean isReviewedLivingWeaponAttach(
                Player player,
                FCollectionView<? extends GameEntity> optionList,
                DelayedReveal delayedReveal,
                SpellAbility ability,
                boolean isOptional,
                Player targetedPlayer,
                Map<String, Object> params) {
            Card source = ability.getHostCard();
            SpellAbility root = ability.getRootAbility();
            SpellAbility cleanup = ability.getSubAbility();
            if (!isReviewedLivingWeaponSource(source)
                    || ability.getApi() != ApiType.Attach
                    || ability.isSpell()
                    || !ability.isTrigger()
                    || ability.isActivatedAbility()
                    || ability.getParent() != root
                    || root == ability
                    || root.getApi() != ApiType.Token
                    || root.getParent() != null
                    || root.getRootAbility() != root
                    || root.getHostCard() != source
                    || root.getSubAbility() != ability
                    || !"b_0_0_phyrexian_germ".equals(root.getParam("TokenScript"))
                    || !"You".equals(root.getParam("TokenOwner"))
                    || !"True".equals(root.getParam("RememberTokens"))
                    || !"Remembered".equals(ability.getParam("Defined"))
                    || ability.hasParam("Object")
                    || ability.hasParam("Choices")
                    || ability.hasParam("PlayerChoices")
                    || ability.hasParam("Optional")
                    || cleanup == null
                    || cleanup.getApi() != ApiType.Cleanup
                    || cleanup.getParent() != ability
                    || cleanup.getRootAbility() != root
                    || cleanup.getHostCard() != source
                    || cleanup.getSubAbility() != null
                    || !"True".equals(cleanup.getParam("ClearRemembered"))
                    || isOptional
                    || delayedReveal != null
                    || targetedPlayer != null
                    || optionList.size() != 1
                    || !(optionList.getFirst() instanceof Card candidate)
                    || !candidate.isToken()
                    || !candidate.isCreature()
                    || !candidate.getType().hasSubtype("Germ")
                    || !candidate.isInZone(ZoneType.Battlefield)
                    || candidate.getOwner() != player
                    || candidate.getController() != player
                    || !source.isRemembered(candidate)
                    || params == null
                    || params.size() != 1
                    || !(params.get("Attachments") instanceof CardCollectionView attachments)
                    || attachments.size() != 1
                    || attachments.getFirst() != source) {
                return false;
            }
            return true;
        }

