        private boolean isReviewedDecimatorTarget(SpellAbility ability) {
            SpellAbility root = ability.getRootAbility();
            SpellAbility effect = root instanceof WrappedAbility wrapper
                    ? wrapper.getWrappedAbility() : root;
            Card source = ability.getHostCard();
            if (source == null || !"Decimator Beetle".equals(source.getName())
                    || root == null || root.getApi() != ApiType.RemoveCounter
                    || !root.isTrigger() || root.isSpell() || root.isActivatedAbility()
                    || root.getParent() != null || root.getRootAbility() != root
                    || root.getMinTargets() != 1 || root.getMaxTargets() != 1
                    || !"Creature.YouCtrl".equals(root.getParam("ValidTgts"))) return false;
            SpellAbility sub = root.getSubAbility();
            // setupTargets reparents the sub-effect to the wrapper after choosing the root target.
            if (sub == null || sub.getApi() != ApiType.PutCounter
                    || sub.getParent() != (ability == root ? effect : root)
                    || sub.getSubAbility() != null
                    || sub.getMinTargets() != 0 || sub.getMaxTargets() != 1
                    || !"Creature".equals(sub.getParam("ValidTgts"))
                    || !"TriggeredDefendingPlayer".equals(sub.getParam("TargetsWithDefinedController"))
                    || (ability != root && ability != sub)) return false;
            for (SpellAbility part : List.of(root, sub)) {
                TargetRestrictions restrictions = part.getTargetRestrictions();
                if (restrictions == null || restrictions.isRandomTarget()
                        || part.isDividedAsYouChoose() || part.hasParam("TargetingPlayer")
                        || !"M1M1".equals(part.getParam("CounterType"))
                        || !"1".equals(part.getParam("CounterNum"))
                        || restrictions.getZone().size() != 1
                        || !restrictions.getZone().contains(ZoneType.Battlefield)) return false;
            }
            return true;
        }

