        /**
         * An optional variable-count basic-land search expressed as repeated
         * single-card callbacks by Forge. The source name is deliberately absent:
         * the executable ability shape, acting player, visible library and card
         * predicate are the boundary.
         */
        private boolean isReviewedRememberedLibrarySplitStep(
                Player player,
                ZoneType destination,
                List<ZoneType> origin,
                SpellAbility ability,
                DelayedReveal delayedReveal,
                String selectPrompt,
                boolean isOptional,
                Player decider) {
            if (ability == null || ability.getHostCard() == null) return false;
            Card source = ability.getHostCard();
            if (origin.equals(List.of(ZoneType.Library))
                    && destination == ZoneType.Hand
                    && ability.getApi() == ApiType.ChangeZone
                    && ability.getParent() != null
                    && ability.getSubAbility() != null
                    && !ability.isSpell()
                    && !ability.isActivatedAbility()
                    && ability.getActivatingPlayer() == player
                    && decider == player
                    && !isOptional
                    && "True".equals(ability.getParam("Mandatory"))
                    && delayedReveal == null
                    && "Select a card to put into your hand".equals(selectPrompt)
                    && "Library".equals(ability.getParam("Origin"))
                    && "Hand".equals(ability.getParam("Destination"))
                    && "Land.IsRemembered".equals(ability.getParam("ChangeType"))
                    && "True".equals(ability.getParam("NoLooking"))
                    && source.getRememberedCount() == 2) {
                return true;
            }
            SpellAbility root = ability.getRootAbility();
            SpellAbility handStep = ability.getSubAbility();
            return origin.equals(List.of(ZoneType.Library))
                    && destination == ZoneType.Battlefield
                    && ability.getApi() == ApiType.ChangeZone
                    && root != null
                    && root != ability
                    && ability.getParent() == root
                    && root.getSubAbility() == ability
                    && handStep != null
                    && root.getApi() == ApiType.ChangeZone
                    && root.isSpell()
                    && !root.isActivatedAbility()
                    && !root.isTrigger()
                    && root.getParent() == null
                    && root.getRootAbility() == root
                    && root.getActivatingPlayer() == player
                    && ability.getActivatingPlayer() == player
                    && decider == player
                    && !isOptional
                    && "True".equals(ability.getParam("Mandatory"))
                    && delayedReveal == null
                    && "Select a card to put onto the battlefield".equals(selectPrompt)
                    && "Library".equals(root.getParam("Origin"))
                    && "Library".equals(root.getParam("Destination"))
                    && "Land.Basic".equals(root.getParam("ChangeType"))
                    && "2".equals(root.getParam("ChangeNum"))
                    && "True".equals(root.getParam("RememberChanged"))
                    && "True".equals(root.getParam("Reveal"))
                    && "False".equals(root.getParam("Shuffle"))
                    && "Land.IsRemembered".equals(ability.getParam("ChangeType"))
                    && "1".equals(ability.getParam("ChangeNum"))
                    && "True".equals(ability.getParam("NoLooking"))
                    && "True".equals(ability.getParam("Tapped"))
                    && "False".equals(ability.getParam("Shuffle"))
                    && handStep.getApi() == ApiType.ChangeZone
                    && handStep.getParent() == ability
                    && handStep.getSubAbility() != null
                    && "Library".equals(handStep.getParam("Origin"))
                    && "Hand".equals(handStep.getParam("Destination"))
                    && "Land.IsRemembered".equals(handStep.getParam("ChangeType"))
                    && "True".equals(handStep.getParam("Mandatory"))
                    && "True".equals(handStep.getParam("NoLooking"))
                    && source.getRememberedCount() == 2;
        }

