        private boolean reviewedCubeZoneCandidate(
                Player player,
                Card card,
                SpellAbility ability,
                boolean rememberedLibrarySplit,
                boolean boundedTriggeredLibraryToHand,
                boolean revealedOpponentHandCreatureChoice) {
            if (!rememberedLibrarySplit
                    && !boundedTriggeredLibraryToHand
                    && !revealedOpponentHandCreatureChoice) return true;
            Card source = ability.getHostCard();
            if (rememberedLibrarySplit) {
                return player.getCardsIn(ZoneType.Library).contains(card)
                        && card.getOwner() == player
                        && card.isLand()
                        && source != null
                        && source.isRemembered(card);
            }
            if (boundedTriggeredLibraryToHand) {
                if (!player.getCardsIn(ZoneType.Library).contains(card) || card.getOwner() != player) {
                    return false;
                }
                String changeType = ability.getParam("ChangeType");
                return switch (changeType) {
                    case "Creature.powerLE2" -> card.isCreature() && card.getNetPower() <= 2;
                    case "Creature.toughnessLE2" -> card.isCreature() && card.getNetToughness() <= 2;
                    case "Instant,Sorcery" -> card.isInstant() || card.isSorcery();
                    default -> false;
                };
            }
            if (!(source != null && source.getFirstRemembered() instanceof Player opponent)) return false;
            return opponent != player
                    && opponent.getCardsIn(ZoneType.Hand).contains(card)
                    && card.getOwner() == opponent
                    && card.isCreature();
        }

