        private boolean reviewedBoundedOptionalZoneCandidate(
                Player player, List<ZoneType> origin, Card card) {
            if (origin.equals(List.of(ZoneType.Library))) {
                return player.getCardsIn(ZoneType.Library).contains(card) && card.isBasicLand();
            }
            return origin.equals(List.of(ZoneType.Hand))
                    && player.getCardsIn(ZoneType.Hand).contains(card)
                    && (card.isCreature() || card.isArtifact() || card.isEnchantment() || card.isLand());
        }

        void verifyReviewedOptionalLibraryCards(
                Player player,
                ZoneType destination,
                List<ZoneType> origin,
                SpellAbility ability,
                CardCollection fetchList,
                int min,
                int max,
                DelayedReveal delayedReveal,
                String selectPrompt,
                Player decider) {
            Card source = ability.getHostCard();
            boolean common = source != null
                    && REVIEWED_OPTIONAL_LIBRARY_MULTI_SEARCHES.contains(source.getName())
                    && origin.equals(List.of(ZoneType.Library))
                    && ability.getApi() == ApiType.ChangeZone
                    && ability.getParent() == null
                    && ability.getSubAbility() == null
                    && !ability.isActivatedAbility()
                    && !ability.isSpell()
                    && ability.getActivatingPlayer() == player
                    && decider == player
                    && "True".equals(ability.getParam("ShuffleNonMandatory"))
                    && !ability.hasParam("Defined")
                    && !ability.hasParam("DefinedPlayer")
                    && !ability.hasParam("Chooser")
                    && min == 0
                    && delayedReveal != null
                    && delayedReveal.getZone().size() == 1
                    && delayedReveal.getZone().contains(ZoneType.Library);
            boolean reviewed = common && switch (source.getName()) {
                case "Land Tax" -> destination == ZoneType.Hand
                        && "Land.Basic".equals(ability.getParam("ChangeType"))
                        && "3".equals(ability.getParam("ChangeNum"))
                        && max == 3
                        && !ability.hasParam("Tapped");
                case "Primeval Titan" -> destination == ZoneType.Battlefield
                        && "Land".equals(ability.getParam("ChangeType"))
                        && "2".equals(ability.getParam("ChangeNum"))
                        && max == 2
                        && "True".equals(ability.getParam("Tapped"));
                default -> false;
            };
            if (!reviewed) {
                throw new IllegalStateException(
                        "Forge reached a multi-card zone choice outside reviewed-optional-library-search-v1: source="
                                + (source == null ? "null" : source.getName())
                                + ", destination=" + destination
                                + ", origin=" + origin
                                + ", parent=" + (ability.getParent() != null)
                                + ", sub=" + (ability.getSubAbility() != null)
                                + ", spell=" + ability.isSpell()
                                + ", activated=" + ability.isActivatedAbility()
                                + ", activatingPlayer=" + (ability.getActivatingPlayer() == player)
                                + ", decider=" + (decider == player)
                                + ", delayedReveal=" + (delayedReveal != null)
                                + ", prompt=" + selectPrompt
                                + ", changeType=" + ability.getParam("ChangeType")
                                + ", changeNum=" + ability.getParam("ChangeNum")
                                + ", min=" + min
                                + ", max=" + max);
            }
            for (Card card : fetchList) {
                if (!card.isInZone(ZoneType.Library)
                        || !player.getCardsIn(ZoneType.Library).contains(card)) {
                    throw new IllegalStateException(
                            "Forge offered an optional-search candidate outside the local library");
                }
            }
        }

