        private static boolean isReviewedRixMaadiDiscard(
                Player player,
                Player discardingPlayer,
                SpellAbility ability,
                CardCollection validCards,
                int min,
                int max,
                CardCollectionView alreadyChosen,
                List<CostPart> parts) {
            if (player == null || discardingPlayer != player || ability == null) return false;
            Card source = ability.getHostCard();
            if (source == null
                    || !"Rix Maadi, Dungeon Palace".equals(source.getName())
                    || !source.isLand()
                    || !source.isInZone(ZoneType.Battlefield)
                    || source.getController() != player
                    || ability.getApi() != ApiType.Discard
                    || !ability.isActivatedAbility()
                    || ability.isSpell()
                    || ability.isTrigger()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || ability.getSubAbility() != null
                    || ability.getActivatingPlayer() != player
                    || ability.usesTargeting()
                    || ability.getTargetRestrictions() != null
                    || !"Player".equals(ability.getParam("Defined"))
                    || !"1".equals(ability.getParam("NumCards"))
                    || !"TgtChoose".equals(ability.getParam("Mode"))
                    || !"True".equals(ability.getParam("SorcerySpeed"))
                    || !ability.getMapParams().keySet().equals(Set.of(
                            "AB", "Cost", "NumCards", "Mode", "Defined", "SorcerySpeed", "SpellDescription"))
                    || min != 1
                    || max != 1
                    || alreadyChosen != validCards
                    || parts.size() != 2
                    || parts.get(0).getClass() != CostTap.class
                    || parts.get(1).getClass() != CostPartMana.class) return false;
            CostPartMana mana = (CostPartMana) parts.get(1);
            if (!"{1}{B}{R}".equals(mana.getMana().getSimpleString())) return false;
            for (Card card : validCards) {
                if (!card.isInZone(ZoneType.Hand) || !player.getCardsIn(ZoneType.Hand).contains(card)) return false;
            }
            return true;
        }

