        CardCollectionView chooseLilianaTwoPilesPartition(
                Player player,
                CardCollectionView sourceList,
                SpellAbility ability,
                String title,
                int min,
                int max,
                boolean isOptional,
                Map<String, Object> params) {
            CardCollectionView battlefield = player.getCardsIn(ZoneType.Battlefield);
            if (!isReviewedLilianaTwoPilesAbility(ability, player)
                    || !"Divide cards into two piles".equals(title)
                    || min != 0
                    || max != sourceList.size()
                    || isOptional
                    || params != null
                    || sourceList.size() != battlefield.size()
                    || !sourceList.containsAll(battlefield)
                    || !battlefield.containsAll(sourceList)) {
                throw new IllegalStateException(
                        "Forge reached a partition outside reviewed-liliana-two-piles-v1"
                                + " (" + describeLilianaTwoPilesAbility(ability, player)
                                + ", title=" + title
                                + ", min=" + min
                                + ", max=" + max
                                + ", optional=" + isOptional
                                + ", params=" + params
                                + ", candidates=" + sourceList.size()
                                + ", battlefield=" + battlefield.size() + ")");
            }
            return new CardCollection(chooseEntities(
                    player, "card-selection", about(ability.getHostCard(), title), sourceList, min, max));
        }

        boolean chooseLilianaPile(
                Player player,
                SpellAbility ability,
                CardCollectionView first,
                CardCollectionView second,
                String faceUp) {
            CardCollectionView battlefield = player.getCardsIn(ZoneType.Battlefield);
            CardCollection union = new CardCollection(first);
            boolean disjoint = Collections.disjoint(first, second);
            union.addAll(second);
            if (!isReviewedLilianaTwoPilesAbility(ability, player)
                    || !"False".equals(faceUp)
                    || !disjoint
                    || union.size() != battlefield.size()
                    || !union.containsAll(battlefield)
                    || !battlefield.containsAll(union)) {
                throw new IllegalStateException(
                        "Forge reached a pile choice outside reviewed-liliana-two-piles-v1"
                                + " (source=" + (ability == null || ability.getHostCard() == null
                                        ? "null" : ability.getHostCard().getName())
                                + ", api=" + (ability == null ? "null" : ability.getApi())
                                + ", faceUp=" + faceUp
                                + ", first=" + first.size()
                                + ", second=" + second.size()
                                + ", battlefield=" + battlefield.size()
                                + ", disjoint=" + disjoint + ")");
            }
            return chooseCardsPile(player, ability, first, second, faceUp);
        }

