        private static CardCollection factOrFictionRememberedCards(SpellAbility ability) {
            if (!isReviewedFactOrFictionTwoPilesAbility(ability)) return null;
            Card source = ability.getHostCard();
            Player caster = ability.getActivatingPlayer();
            if (caster == null) return null;
            CardCollection remembered = new CardCollection();
            for (Object value : source.getRemembered()) {
                if (!(value instanceof Card card)
                        || !card.isInZone(ZoneType.Library)
                        || !caster.getCardsIn(ZoneType.Library).contains(card)) {
                    return null;
                }
                remembered.add(card);
            }
            return remembered;
        }

