        private static CardCollection xenagosUltimateEligibleCards(Card source) {
            CardCollection eligible = new CardCollection();
            if (source == null) return eligible;
            for (Object remembered : source.getRemembered()) {
                if (remembered instanceof Card card
                        && remembered == card
                        && card.isInZone(ZoneType.Exile)
                        && (card.isCreature() || card.isLand())) {
                    eligible.add(card);
                }
            }
            eligible.sort();
            return eligible;
        }

        private static boolean sameCardIdentities(
                CardCollectionView offered, CardCollectionView expected) {
            if (offered.size() != expected.size()) return false;
            for (int index = 0; index < offered.size(); index++) {
                if (offered.get(index) != expected.get(index)) return false;
            }
            return true;
        }

        List<Card> chooseXenagosUltimateCards(
                Player player,
                ZoneType destination,
                List<ZoneType> origin,
                SpellAbility ability,
                CardCollection fetchList,
                int minimum,
                int maximum,
                DelayedReveal delayedReveal,
                String prompt,
                Player decider) {
            Card source = ability == null ? null : ability.getHostCard();
            CardCollection expected = xenagosUltimateEligibleCards(source);
            if (!isReviewedXenagosUltimateSelection(ability, player)
                    || destination != ZoneType.Battlefield
                    || !origin.equals(List.of(ZoneType.Exile))
                    || decider != player
                    || delayedReveal != null
                    || minimum != 0
                    || maximum != expected.size()
                    || !sameCardIdentities(fetchList, expected)) {
                throw new IllegalStateException("outside reviewed-xenagos-ultimate-selection-v1");
            }
            return chooseEntities(
                    player,
                    "zone-card-selection",
                    about(source, prompt),
                    fetchList,
                    minimum,
                    maximum);
        }

