        private static boolean isReviewedHideawayDigAbility(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            SpellAbility effect = ability.getSubAbility();
            SpellAbility cleanup = effect == null ? null : effect.getSubAbility();
            SpellAbility effectParent = effect == null ? null : effect.getParent();
            if (!(effectParent instanceof WrappedAbility wrapped)) return false;
            return isReviewedHideawaySource(source)
                    && source.isInZone(ZoneType.Battlefield)
                    && wrapped.getWrappedAbility() == ability
                    && wrapped.getHostCard() == source
                    && wrapped.getSubAbility() == effect
                    && wrapped.isTrigger()
                    && ability.getApi() == ApiType.Dig
                    && ability.isTrigger()
                    && !ability.isSpell()
                    && !ability.isActivatedAbility()
                    && ability.getParent() == null
                    && ability.getRootAbility() == ability
                    && "You".equals(ability.getParam("Defined"))
                    && "4".equals(ability.getParam("DigNum"))
                    && "Exile".equals(ability.getParam("DestinationZone"))
                    && "True".equals(ability.getParam("ExileFaceDown"))
                    && "True".equals(ability.getParam("RememberChanged"))
                    && "True".equals(ability.getParam("RestRandomOrder"))
                    && !ability.hasParam("ChangeNum")
                    && !ability.hasParam("ChangeValid")
                    && !ability.hasParam("Optional")
                    && !ability.hasParam("SourceZone")
                    && !ability.hasParam("DestinationZone2")
                    && !ability.hasParam("Chooser")
                    && effect != null
                    && effect.getParent() == wrapped
                    && effect.getRootAbility() == wrapped
                    && effect.getApi() == ApiType.Effect
                    && "STHideawayEffectLookAtCard".equals(effect.getParam("StaticAbilities"))
                    && "Exile".equals(effect.getParam("ForgetOnMoved"))
                    && "Remembered".equals(effect.getParam("RememberObjects"))
                    && "Permanent".equals(effect.getParam("Duration"))
                    && cleanup != null
                    && cleanup.getParent() == effect
                    && cleanup.getRootAbility() == wrapped
                    && cleanup.getApi() == ApiType.Cleanup
                    && "True".equals(cleanup.getParam("ClearRemembered"))
                    && cleanup.getSubAbility() == null;
        }

        private static boolean isReviewedHideawayPlayAbility(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            Cost cost = ability.getPayCosts();
            List<CostPart> parts = cost == null ? List.of() : cost.getCostParts();
            String expectedMana = "Windbrisk Heights".equals(source == null ? null : source.getName())
                    ? "{W}"
                    : "{U}";
            boolean exactCondition = source != null
                    && "X".equals(ability.getParam("ConditionCheckSVar"))
                    && ("Windbrisk Heights".equals(source.getName())
                            ? "GE3".equals(ability.getParam("ConditionSVarCompare"))
                                    && "True".equals(ability.getParam("PlayerTurn"))
                                    && "Count$AttackersDeclared".equals(source.getSVar("X"))
                            : "LE20".equals(ability.getParam("ConditionSVarCompare"))
                                    && !ability.hasParam("PlayerTurn")
                                    && "PlayerCountPlayers$LowestValidLibrary Card.YouOwn".equals(source.getSVar("X")));
            return isReviewedHideawaySource(source)
                    && source.isInZone(ZoneType.Battlefield)
                    && ability.getApi() == ApiType.Play
                    && ability.isActivatedAbility()
                    && !ability.isSpell()
                    && !ability.isTrigger()
                    && ability.getParent() == null
                    && ability.getRootAbility() == ability
                    && ability.getSubAbility() == null
                    && "ExiledWith".equals(ability.getParam("Defined"))
                    && "All".equals(ability.getParam("Amount"))
                    && "You".equals(ability.getParam("Controller"))
                    && "True".equals(ability.getParam("WithoutManaCost"))
                    && "True".equals(ability.getParam("Optional"))
                    && exactCondition
                    && parts.size() == 2
                    && parts.get(0).getClass() == CostTap.class
                    && parts.get(1).getClass() == CostPartMana.class
                    && expectedMana.equals(((CostPartMana) parts.get(1)).getMana().getSimpleString());
        }

