        CardCollectionView chooseTreacheryLandsToUntap(
                Player player,
                CardCollectionView sourceList,
                SpellAbility ability,
                String title,
                int min,
                int max,
                boolean isOptional,
                Map<String, Object> params) {
            CardCollection battlefieldUntappableLands = new CardCollection();
            if (ability != null && ability.getHostCard() != null) {
                for (Card card : player.getGame().getCardsIn(ZoneType.Battlefield)) {
                    if (card.isLand() && card.canUntap(null, false)) {
                        battlefieldUntappableLands.add(card);
                    }
                }
            }
            boolean candidatesValid = sourceList.size() == battlefieldUntappableLands.size()
                    && sourceList.containsAll(battlefieldUntappableLands)
                    && battlefieldUntappableLands.containsAll(sourceList);
            for (Card card : sourceList) {
                if (card.getZone() == null
                        || card.getZone().getZoneType() != ZoneType.Battlefield
                        || !card.isLand()
                        || !card.canUntap(null, false)) {
                    candidatesValid = false;
                }
            }
            if (!isReviewedTreacheryUntapAbility(ability)
                    || ability.getActivatingPlayer() != player
                    || !"Select cards to untap".equals(title)
                    || min != 0
                    || max != 5
                    || !isOptional
                    || params != null
                    || !candidatesValid) {
                throw new IllegalStateException(
                        "Forge reached a choice outside reviewed-treachery-v1"
                                + " (source=" + (ability == null || ability.getHostCard() == null
                                        ? "null" : ability.getHostCard().getName())
                                + ", api=" + (ability == null ? "null" : ability.getApi())
                                + ", trigger=" + (ability != null && ability.isTrigger())
                                + ", chooserIsActivator=" + (ability != null
                                        && ability.getActivatingPlayer() == player)
                                + ", title=" + title
                                + ", min=" + min
                                + ", max=" + max
                                + ", optional=" + isOptional
                                + ", params=" + params
                                + ", candidates=" + sourceList.size()
                                + ", battlefieldUntappableLands=" + battlefieldUntappableLands.size()
                                + ", candidatesValid=" + candidatesValid + ")");
            }
            return new CardCollection(chooseEntities(
                    player,
                    "card-selection",
                    about(ability.getHostCard(), title),
                    sourceList,
                    min,
                    max));
        }

