        CardCollectionView chooseFactOrFictionPartition(
                Player player,
                CardCollectionView sourceList,
                SpellAbility ability,
                String title,
                int min,
                int max,
                boolean isOptional,
                Map<String, Object> params) {
            CardCollection remembered = factOrFictionRememberedCards(ability);
            if (!isReviewedFactOrFictionTwoPilesAbility(ability)
                    || !player.isOpponentOf(ability.getActivatingPlayer())
                    || !"Divide cards into two piles".equals(title)
                    || min != 0
                    || max != sourceList.size()
                    || isOptional
                    || params != null
                    || sourceList.isEmpty()
                    || sourceList.size() > 5
                    || remembered == null
                    || sourceList.size() != remembered.size()
                    || !sourceList.containsAll(remembered)
                    || !remembered.containsAll(sourceList)) {
                throw new IllegalStateException(
                        "Forge reached a partition outside reviewed-fact-or-fiction-v1"
                                + " (source=" + (ability == null || ability.getHostCard() == null
                                        ? "null" : ability.getHostCard().getName())
                                + ", api=" + (ability == null ? "null" : ability.getApi())
                                + ", separatorIsOpponent=" + (ability != null
                                        && player.isOpponentOf(ability.getActivatingPlayer()))
                                + ", title=" + title
                                + ", min=" + min
                                + ", max=" + max
                                + ", optional=" + isOptional
                                + ", params=" + params
                                + ", candidates=" + sourceList.size()
                                + ", remembered=" + (remembered == null ? "invalid" : remembered.size()) + ")");
            }
            return new CardCollection(chooseEntities(
                    player, "card-selection", about(ability.getHostCard(), title), sourceList, min, max));
        }

        boolean chooseFactOrFictionPile(
                Player player,
                SpellAbility ability,
                CardCollectionView first,
                CardCollectionView second,
                String faceUp) {
            CardCollection remembered = factOrFictionRememberedCards(ability);
            CardCollection union = new CardCollection(first);
            boolean disjoint = Collections.disjoint(first, second);
            union.addAll(second);
            if (!isReviewedFactOrFictionTwoPilesAbility(ability)
                    || ability.getActivatingPlayer() != player
                    || !"False".equals(faceUp)
                    || remembered == null
                    || !disjoint
                    || union.size() != remembered.size()
                    || !union.containsAll(remembered)
                    || !remembered.containsAll(union)) {
                throw new IllegalStateException(
                        "Forge reached a pile choice outside reviewed-fact-or-fiction-v1"
                                + " (source=" + (ability == null || ability.getHostCard() == null
                                        ? "null" : ability.getHostCard().getName())
                                + ", api=" + (ability == null ? "null" : ability.getApi())
                                + ", chooserIsCaster=" + (ability != null
                                        && ability.getActivatingPlayer() == player)
                                + ", faceUp=" + faceUp
                                + ", first=" + first.size()
                                + ", second=" + second.size()
                                + ", remembered=" + (remembered == null ? "invalid" : remembered.size())
                                + ", disjoint=" + disjoint + ")");
            }
            List<ChoiceTarget> firstTargets = new ArrayList<>();
            for (Card card : first) firstTargets.add(cardTarget(card));
            List<ChoiceTarget> secondTargets = new ArrayList<>();
            for (Card card : second) secondTargets.add(cardTarget(card));
            List<Choice> choices = List.of(
                    new Choice(
                            "choose-pile-first",
                            describePile("Pile 1", first, true),
                            Boolean.TRUE,
                            firstTargets),
                    new Choice(
                            "choose-pile-second",
                            describePile("Pile 2", second, true),
                            Boolean.FALSE,
                            secondTargets));
            Object value = awaitChoice(player, "choose-pile", about(ability.getHostCard(), "Choose a pile"), choices)
                    .value;
            if (!(value instanceof Boolean selected)) {
                throw new IllegalStateException("selected Fact or Fiction pile disappeared");
            }
            return selected.booleanValue();
        }

