        private CardCollection chooseExactHandDiscard(
                Player player, CardCollection validCards, String sourceName) {
            CardCollectionView localHand = player.getCardsIn(ZoneType.Hand);
            List<Choice> choices = new ArrayList<>();
            for (Card card : validCards) {
                if (!card.isInZone(ZoneType.Hand) || !localHand.contains(card)) {
                    throw new IllegalStateException("Forge offered a discard candidate outside the local hand");
                }
                String id = "discard-card-" + card.getId();
                choices.add(new Choice(
                        id,
                        "Discard " + card.getName() + " [" + id + "]",
                        card,
                        List.of(new ChoiceTarget("forge-card-" + card.getId(), card.getName()))));
            }
            if (choices.isEmpty()) {
                throw new IllegalStateException("Forge offered no card for mandatory " + sourceName + " discard");
            }
            Object value = awaitChoice(player, "hand-card-selection", "Choose one card to discard", choices).value;
            if (!(value instanceof Card card)
                    || !validCards.contains(card)
                    || !card.isInZone(ZoneType.Hand)
                    || !player.getCardsIn(ZoneType.Hand).contains(card)) {
                throw new IllegalStateException("selected discard card disappeared");
            }
            return new CardCollection(card);
        }

