        /** The two exact hand payments admitted by discard-source-sacrifice-cost-v1. */
        PaymentDecision chooseDiscardCost(
                Player payer, SpellAbility ability, CostDiscard cost, boolean effect) {
            if (!cost.canPay(ability, payer, effect)) return null;
            Card source = ability.getHostCard();
            PaymentDecision decision;
            if ("Hand".equals(cost.getType())) {
                CardCollection hand = new CardCollection(payer.getCardsIn(ZoneType.Hand));
                boolean confirmed = confirm(payer, "cost-discard-hand-confirm",
                        about(source, "Discard your hand to pay this cost?"),
                        "Discard your hand", "Cancel cost payment", sourceAndExiledTargets(source));
                if (!confirmed) return null;
                if (hand.size() > 1) {
                    hand = new CardCollection(
                            payer.getController().orderMoveToZoneList(hand, ZoneType.Graveyard, ability));
                }
                decision = PaymentDecision.card(hand);
            } else {
                CardCollection hand = new CardCollection(payer.getCardsIn(ZoneType.Hand));
                hand = CardLists.getValidCards(hand, cost.getType().split(";"), payer, source, ability);
                if (source.isInZone(ZoneType.Hand) && payer.equals(source.getOwner())) hand.remove(source);
                List<Choice> choices = new ArrayList<>();
                for (Card card : hand) {
                    String id = "cost-discard-" + card.getId();
                    choices.add(new Choice(id, "Discard " + card.getName() + " [" + id + "]",
                            card, List.of(cardTarget(card))));
                }
                choices.add(new Choice(
                        "cost-discard-cancel", "Cancel cost payment", CancelCostPayment.INSTANCE));
                Object selected = awaitChoice(payer, "cost-discard-selection",
                        about(source, "Choose a card to discard"), choices).value;
                if (selected == CancelCostPayment.INSTANCE) return null;
                if (!(selected instanceof Card card) || !hand.contains(card)) {
                    throw new IllegalStateException("selected discard-cost card became illegal");
                }
                decision = PaymentDecision.card(card);
            }
            if (!cost.canPay(ability, payer, effect)) return null;
            CardCollection current = new CardCollection(payer.getCardsIn(ZoneType.Hand));
            if (!current.containsAll(decision.cards)) return null;
            if ("Hand".equals(cost.getType()) && current.size() != decision.cards.size()) return null;
            return decision;
        }

