        /**
         * Several lists in a row, which is how Forge asks a card that names groups.
         *
         * Forge's own client walks the map and asks each entry as its own
         * nothing-or-one question, using the entry's key as the title, so this
         * asks the same sequence rather than flattening it into one list the
         * person would have to read the grouping out of.
         */
        @Override
        public CardCollection chooseCardsForEffectMultiple(
                Map<String, CardCollection> validMap, SpellAbility ability, String title, boolean isOptional) {
            String fallback = title == null || title.isBlank() ? "Choose a card" : title;
            List<Card> chosen = new ArrayList<>();
            for (Map.Entry<String, CardCollection> entry : validMap.entrySet()) {
                chosen.addAll(session.chooseEntities(
                        getPlayer(),
                        "card-selection",
                        question(ability, entry.getKey(), fallback),
                        entry.getValue(),
                        0,
                        1));
            }
            return new CardCollection(chosen);
        }

        @Override
        public <T extends GameEntity> T chooseSingleEntityForEffect(
                FCollectionView<T> optionList,
                DelayedReveal delayedReveal,
                SpellAbility ability,
                String title,
                boolean isOptional,
                Player targetedPlayer,
                Map<String, Object> params) {
            if (ability != null && ability.isMutate()) {
                if (!isReviewedSawtuskMutateTopChoice(
                        getPlayer(), optionList, delayedReveal, ability, title, isOptional, targetedPlayer, params)) {
                    throw new IllegalStateException("outside reviewed-sawtusk-mutate-top-choice-v1");
                }
                return session.chooseEntity(
                        getPlayer(),
                        "entity-selection",
                        question(ability, title, "Choose which creature is on top"),
                        optionList,
                        false,
                        null);
            }
            if (ability != null && session.isReviewedHideawaySource(ability.getHostCard())) {
                return session.chooseHideawayPlayCard(
                        getPlayer(), optionList, delayedReveal, ability, isOptional, targetedPlayer, params);
            }
            if (ability != null && session.isReviewedLivingWeaponSource(ability.getHostCard())) {
                if (session.isReviewedLivingWeaponAttach(
                        getPlayer(), optionList, delayedReveal, ability, isOptional, targetedPlayer, params)) {
                    return optionList.getFirst();
                }
                if (!session.isReviewedLivingWeaponEquip(ability)) {
                    throw new IllegalStateException("outside reviewed-living-weapon-attach-v1");
                }
            }
            if (ability != null && ability.getApi() == ApiType.CompanionChoose) {
                if (!isOptional
                        || delayedReveal != null
                        || targetedPlayer != null
                        || params != null
                        || optionList.size() != 1
                        || !(optionList.getFirst() instanceof Card candidate)
                        || ability.getHostCard() != candidate
                        || ability.getActivatingPlayer() != getPlayer()
                        || candidate.getOwner() != getPlayer()
                        || candidate.getController() != getPlayer()
                        || !candidate.isInZone(ZoneType.Sideboard)) {
                    throw new IllegalStateException("outside reviewed-companion-choice-v1");
                }
                Collection<KeywordInterface> companions = candidate.getKeywords(Keyword.COMPANION);
                String expected = switch (candidate.getName()) {
                    case "Yorion, Sky Nomad" ->
                        "Companion:Special:DeckSizePlus20:Your starting deck contains at least twenty cards more than the minimum deck size.";
                    case "Obosh, the Preypiercer" ->
                        "Companion:Card.cmcM21,Land:Your starting deck contains only cards with odd mana value and land cards.";
                    default -> null;
                };
                if (expected == null
                        || companions.size() != 1
                        || !expected.equals(companions.iterator().next().getOriginal())) {
                    throw new IllegalStateException("outside reviewed-companion-choice-v1");
                }
                return session.chooseEntity(
                        getPlayer(),
                        "companion-selection",
                        question(ability, title, "Choose a companion"),
                        optionList,
                        true,
                        null);
            }
            if (!isOptional && optionList.size() == 1) return optionList.getFirst();
            return session.chooseEntity(
                    getPlayer(),
                    "entity-selection",
                    question(ability, title, "Choose one"),
                    optionList,
                    isOptional,
                    delayedReveal);
        }

        private static <T extends GameEntity> boolean isReviewedSawtuskMutateTopChoice(
                Player chooser,
                FCollectionView<T> optionList,
                DelayedReveal delayedReveal,
                SpellAbility ability,
                String title,
                boolean isOptional,
                Player targetedPlayer,
                Map<String, Object> params) {
            Card source = ability.getHostCard();
            Card target = ability.getTargets().getFirstTargetedCard();
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            TargetRestrictions targets = ability.getTargetRestrictions();
            if (source == null
                    || !"Sawtusk Demolisher".equals(reviewedSourceName(source))
                    || ability.getApi() != ApiType.Mutate
                    || !ability.isMutate()
                    || !ability.isSpell()
                    || ability.isActivatedAbility()
                    || ability.isTrigger()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || ability.getSubAbility() != null
                    || !ability.isIntrinsic()
                    || ability.getActivatingPlayer() != chooser
                    || source.getOwner() != chooser
                    || source.getController() != chooser
                    || !source.isInZone(ZoneType.Stack)
                    || targets == null
                    || ability.getMinTargets() != 1
                    || ability.getMaxTargets() != 1
                    || targets.isRandomTarget()
                    || targets.getZone().size() != 1
                    || !targets.getZone().contains(ZoneType.Battlefield)
                    || !"Creature.sharesOwnerWith+nonHuman".equals(ability.getParam("ValidTgts"))
                    || parts.size() != 1
                    || parts.get(0).getClass() != CostPartMana.class
                    || !"{3}{G}".equals(((CostPartMana) parts.get(0)).getMana().getSimpleString())
                    || target == null
                    || !target.isInZone(ZoneType.Battlefield)
                    || !target.isCreature()
                    || target.getType().hasSubtype("Human")
                    || target.getOwner() != chooser
                    || optionList.size() != 2
                    || !optionList.contains(source)
                    || !optionList.contains(target)
                    || delayedReveal != null
                    || isOptional
                    || targetedPlayer != null
                    || params == null
                    || !params.isEmpty()
                    || !"Choose which creature to be the top".equals(title)) return false;
            for (T option : optionList) {
                if (!(option instanceof Card card) || (card != source && card != target)) return false;
            }
            return true;
        }

        @Override
        public <T extends GameEntity> List<T> chooseEntitiesForEffect(
                FCollectionView<T> optionList,
                int min,
                int max,
                DelayedReveal delayedReveal,
                SpellAbility ability,
                String title,
                Player targetedPlayer,
                Map<String, Object> params) {
            if (ability != null
                    && ability.getHostCard() != null
                    && "Expressive Iteration".equals(ability.getHostCard().getName())) {
                return session.chooseExpressiveIterationCard(
                        getPlayer(), optionList, min, max, delayedReveal,
                        ability, targetedPlayer, params);
            }
            if (ability != null && "Yawgmoth, Thran Physician".equals(
                    reviewedSourceName(ability.getHostCard()))) {
                if (!isReviewedYawgmothProliferateChoice(
                        getPlayer(), optionList, min, max, delayedReveal,
                        ability, targetedPlayer, params)) {
                    throw new IllegalStateException("outside reviewed-yawgmoth-proliferate-choice-v1");
                }
                return session.chooseEntities(
                        getPlayer(),
                        "entity-selection",
                        question(ability, title, "Choose permanents and players to proliferate"),
                        optionList,
                        min,
                        max,
                        delayedReveal);
            }
            if (ability != null
                    && ability.getHostCard() != null
                    && "Turntimber Symbiosis".equals(ability.getHostCard().getName())) {
                return session.chooseTurntimberSymbiosisCreature(
                        getPlayer(), optionList, min, max, delayedReveal, ability, targetedPlayer, params);
            }
            if (ability != null && session.isReviewedBlueLibrarySelectionSource(ability.getHostCard())) {
                return session.chooseBlueLibrarySelectionCard(
                        getPlayer(), optionList, min, max, delayedReveal, ability, targetedPlayer, params);
            }
            if (ability != null && session.isReviewedHideawaySource(ability.getHostCard())) {
                return session.chooseHideawayCard(
                        getPlayer(), optionList, min, max, delayedReveal, ability, targetedPlayer, params);
            }
            if (ability != null
                    && ability.getHostCard() != null
                    && "Satyr Wayfinder".equals(ability.getHostCard().getName())) {
                return session.chooseSatyrWayfinderLand(
                        getPlayer(),
                        optionList,
                        min,
                        max,
                        delayedReveal,
                        ability,
                        targetedPlayer,
                        params);
            }
            return session.chooseEntities(
                    getPlayer(),
                    "entity-selection",
                    question(ability, title, "Choose"),
                    optionList,
                    min,
                    max,
                    delayedReveal);
        }

        private static <T extends GameEntity> boolean isReviewedYawgmothProliferateChoice(
                Player chooser,
                FCollectionView<T> optionList,
                int min,
                int max,
                DelayedReveal delayedReveal,
                SpellAbility ability,
                Player targetedPlayer,
                Map<String, Object> params) {
            if (!isReviewedYawgmothProliferateAbility(ability)
                    || ability.getActivatingPlayer() != chooser
                    || ability.getHostCard().getController() != chooser
                    || min != 0
                    || max != optionList.size()
                    || delayedReveal != null
                    || targetedPlayer != chooser
                    || params != null) return false;
            List<GameEntity> expected = new ArrayList<>();
            for (Player player : ability.getHostCard().getGame().getPlayers()) {
                if (!player.getCounters().isEmpty()) expected.add(player);
            }
            for (Card card : ability.getHostCard().getGame().getCardsIn(ZoneType.Battlefield)) {
                if (!card.getCounters().isEmpty()) expected.add(card);
            }
            if (expected.size() != optionList.size() || !expected.containsAll(optionList)) return false;
            for (T entity : optionList) {
                if (entity.getCounters().isEmpty()) return false;
            }
            return true;
        }

