        /** Mindslaver's exact player target and fixed source-payment activation. */
        private static boolean isReviewedBomatCourierActivation(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            if (source == null
                    || !"Bomat Courier".equals(reviewedSourceName(source))
                    || !source.isInZone(ZoneType.Battlefield)
                    || !source.isArtifact()
                    || !source.isCreature()
                    || !source.getType().hasSubtype("Construct")
                    || ability.getApi() != ApiType.ChangeZoneAll
                    || !ability.isActivatedAbility()
                    || ability.isSpell()
                    || ability.isTrigger()
                    || !ability.isIntrinsic()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || ability.getSubAbility() != null
                    || ability.usesTargeting()
                    || !ability.getTargets().isEmpty()
                    || !"Card.ExiledWithSource".equals(ability.getParam("ChangeType"))
                    || !"Exile".equals(ability.getParam("Origin"))
                    || !"Hand".equals(ability.getParam("Destination"))
                    || parts.size() != 3
                    || parts.get(0).getClass() != CostPartMana.class
                    || !"{R}".equals(((CostPartMana) parts.get(0)).getMana().getSimpleString())
                    || parts.get(1).getClass() != CostDiscard.class
                    || parts.get(2).getClass() != CostSacrifice.class) return false;
            CostDiscard discard = (CostDiscard) parts.get(1);
            CostSacrifice sacrifice = (CostSacrifice) parts.get(2);
            return !discard.payCostFromSource()
                    && "0".equals(discard.getAmount())
                    && "Hand".equals(discard.getType())
                    && discard.getTypeDescription() == null
                    && sacrifice.payCostFromSource()
                    && "1".equals(sacrifice.getAmount())
                    && "CARDNAME".equals(sacrifice.getType())
                    && sacrifice.getTypeDescription() == null;
        }

