        /**
         * reviewed-emrakul-promised-end-next-turn-v1: the SpellCast trigger's ControlPlayer
         * sub-ability that grants control of a targeted opponent during that opponent's next
         * turn, delaying an extra turn for that opponent afterward via DelayedTrigger. Same
         * ControlPlayer engine mechanism as Mindslaver, reviewed separately because Emrakul
         * reaches it as a triggered spell-cast effect rather than a paid activated ability.
         */
        private static boolean isReviewedEmrakulPromisedEndControlAbility(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            TargetRestrictions targets = ability.getTargetRestrictions();
            SpellAbility sub = ability.getSubAbility();
            if (source == null
                    || !"Emrakul, the Promised End".equals(reviewedSourceName(source))
                    || ability.getApi() != ApiType.ControlPlayer
                    || ability.isActivatedAbility()
                    || ability.isSpell()
                    || !ability.isTrigger()
                    || !ability.isIntrinsic()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || !"Opponent".equals(ability.getParam("ValidTgts"))
                    || ability.hasParam("TargetingPlayer")
                    || targets == null
                    || ability.getMinTargets() != 1
                    || ability.getMaxTargets() != 1
                    || targets.isRandomTarget()
                    || sub == null
                    || sub.getApi() != ApiType.DelayedTrigger) return false;
            return "Phase".equals(sub.getParam("Mode"))
                    && "Cleanup".equals(sub.getParam("Phase"))
                    && "Targeted".equals(sub.getParam("DelayedTriggerDefinedPlayer"))
                    && "True".equals(sub.getParam("Static"));
        }

        private static String describeMindslaverAbility(SpellAbility ability) {
            Card source = ability == null ? null : ability.getHostCard();
            TargetRestrictions targets = ability == null ? null : ability.getTargetRestrictions();
            Cost costs = ability == null ? null : ability.getPayCosts();
            List<CostPart> parts = costs == null ? List.of() : costs.getCostParts();
            return "source=" + (source == null ? "null" : reviewedSourceName(source))
                    + ", artifact=" + (source != null && source.isArtifact())
                    + ", api=" + (ability == null ? "null" : ability.getApi())
                    + ", flags=" + (ability == null
                            ? "null"
                            : ability.isSpell() + "/" + ability.isTrigger() + "/"
                                    + ability.isActivatedAbility() + "/" + ability.isIntrinsic())
                    + ", parent=" + (ability == null || ability.getParent() == null
                            ? "null"
                            : ability.getParent().getApi())
                    + ", rootSelf=" + (ability != null && ability.getRootAbility() == ability)
                    + ", sub=" + (ability == null || ability.getSubAbility() == null
                            ? "null"
                            : ability.getSubAbility().getApi())
                    + ", valid=" + (ability == null ? "null" : ability.getParam("ValidTgts"))
                    + ", minMax=" + (ability == null
                            ? "null"
                            : ability.getMinTargets() + "/" + ability.getMaxTargets())
                    + ", random=" + (targets != null && targets.isRandomTarget())
                    + ", parts=" + parts.stream()
                            .map(part -> part.getClass().getSimpleName() + ":" + part)
                            .toList();
        }

