        private static boolean controlsGoldspanDragon(Player player) {
            if (player == null) return false;
            for (Card card : player.getCardsIn(ZoneType.Battlefield)) {
                if ("Goldspan Dragon".equals(card.getName())
                        && card.getController() == player) return true;
            }
            return false;
        }

