        /** Exact cost-bearing abilities from the reviewed generated-token sacrifice cohort. */
        private static boolean isReviewedGeneratedTokenSacrificeCost(
                CostSacrifice cost, SpellAbility ability) {
            Card source = ability.getHostCard();
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            if (source == null
                    || !ability.isActivatedAbility()
                    || ability.isSpell()
                    || ability.isTrigger()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || cost.payCostFromSource()
                    || !"1".equals(cost.getAmount())
                    || parts.isEmpty()
                    || parts.get(parts.size() - 1).getClass() != CostSacrifice.class) return false;

            if ("Koma, Cosmos Serpent".equals(reviewedSourceName(source))) {
                List<AbilitySub> modes = ability.getAdditionalAbilityList("Choices");
                SpellAbility selectedMode = ability.getSubAbility();
                return ability.getApi() == ApiType.Charm
                        && "DBTap,DBPump".equals(ability.getParam("Choices"))
                        && "Serpent.Other".equals(cost.getType())
                        && "another Serpent".equals(cost.getTypeDescription())
                        && parts.size() == 1
                        && modes.size() == 2
                        && isReviewedKomaTapMode(modes.get(0), ability)
                        && isReviewedKomaPumpMode(modes.get(1), ability)
                        && selectedMode instanceof AbilitySub selected
                        && (isReviewedKomaTapMode(selected, ability)
                                || isReviewedKomaPumpMode(selected, ability));
            }
            if ("Retrofitter Foundry".equals(reviewedSourceName(source))) {
                if (ability.getApi() != ApiType.Token
                        || ability.getSubAbility() != null
                        || !"You".equals(ability.getParam("TokenOwner"))
                        || ability.hasParam("TokenAmount")
                        || cost.getTypeDescription() != null) return false;
                if ("Servo".equals(cost.getType())) {
                    return "c_1_1_a_thopter_flying".equals(ability.getParam("TokenScript"))
                            && parts.size() == 3
                            && parts.get(0).getClass() == CostTap.class
                            && parts.get(1).getClass() == CostPartMana.class
                            && "{1}".equals(((CostPartMana) parts.get(1)).getMana().getSimpleString());
                }
                return "Thopter".equals(cost.getType())
                        && "c_4_4_a_construct".equals(ability.getParam("TokenScript"))
                        && parts.size() == 2
                        && parts.get(0).getClass() == CostTap.class;
            }
            return "Treasure Map".equals(reviewedSourceName(source))
                    && "Treasure Cove".equals(source.getName())
                    && ability.getApi() == ApiType.Draw
                    && ability.getSubAbility() == null
                    && "1".equals(ability.getParam("NumCards"))
                    && "Treasure".equals(cost.getType())
                    && cost.getTypeDescription() == null
                    && parts.size() == 2
                    && parts.get(0).getClass() == CostTap.class;
        }

        private static boolean isReviewedKomaTapMode(AbilitySub mode, SpellAbility root) {
            TargetRestrictions targets = mode.getTargetRestrictions();
            AbilitySub constrict = mode.getSubAbility();
            return mode.getHostCard() == root.getHostCard()
                    && mode.getParent() == root
                    && mode.getRootAbility() == root
                    && mode.getApi() == ApiType.Tap
                    && !mode.isActivatedAbility()
                    && !mode.isSpell()
                    && !mode.isTrigger()
                    && mode.getMinTargets() == 1
                    && mode.getMaxTargets() == 1
                    && targets != null
                    && !targets.isRandomTarget()
                    && targets.getZone().size() == 1
                    && targets.getZone().contains(ZoneType.Battlefield)
                    && "Permanent".equals(mode.getParam("ValidTgts"))
                    && constrict != null
                    && constrict.getParent() == mode
                    && constrict.getRootAbility() == root
                    && constrict.getApi() == ApiType.Effect
                    && "ParentTarget".equals(constrict.getParam("RememberObjects"))
                    && "DBCantBeActivated".equals(constrict.getParam("StaticAbilities"))
                    && "Battlefield".equals(constrict.getParam("ForgetOnMoved"))
                    && constrict.getSubAbility() == null;
        }

        private static boolean isReviewedKomaPumpMode(AbilitySub mode, SpellAbility root) {
            return mode.getHostCard() == root.getHostCard()
                    && mode.getParent() == root
                    && mode.getRootAbility() == root
                    && mode.getApi() == ApiType.Pump
                    && !mode.isActivatedAbility()
                    && !mode.isSpell()
                    && !mode.isTrigger()
                    && "Self".equals(mode.getParam("Defined"))
                    && "Indestructible".equals(mode.getParam("KW"))
                    && mode.getSubAbility() == null;
        }

        private static boolean isReviewedChosenCreatureSacrificeCost(
                CostSacrifice cost, SpellAbility ability) {
            return isReviewedOtherCreatureSacrificeCost(cost, ability)
                    || isReviewedKalitasSacrificeCost(cost, ability)
                    || isReviewedBirthingPodSacrificeCost(cost, ability)
                    || isReviewedRecurringNightmareSacrificeCost(cost, ability)
                    || isReviewedMagusOfTheOrderSacrificeCost(cost, ability)
                    || isReviewedNaturalOrderSacrificeCost(cost, ability)
                    || isReviewedFalkenrathAristocratSacrificeCost(cost, ability)
                    || (isReviewedCavalierReflexiveSacrificeAbility(ability)
                            && ability.getPayCosts().getCostParts().get(0) == cost);
        }

        private static boolean isReviewedPlaneswalkerUnlessSacrificeCost(
                Cost cost, SpellAbility ability) {
            if (cost == null || cost.getCostParts().size() != 1
                    || cost.getCostParts().get(0).getClass() != CostSacrifice.class) return false;
            return isReviewedPlaneswalkerUnlessSacrificePart(
                    (CostSacrifice) cost.getCostParts().get(0), ability);
        }

        private static boolean isReviewedPlaneswalkerUnlessSacrificePart(
                CostSacrifice sacrifice, SpellAbility ability) {
            if (ability == null || sacrifice == null) return false;
            Card source = ability.getHostCard();
            String name = reviewedSourceName(source);
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            CostRemoveCounter loyalty = parts.size() == 1
                            && parts.get(0).getClass() == CostRemoveCounter.class
                    ? (CostRemoveCounter) parts.get(0)
                    : null;
            if (source == null
                    || !source.isInZone(ZoneType.Battlefield)
                    || !ability.isActivatedAbility()
                    || ability.isSpell()
                    || ability.isTrigger()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || !"True".equals(ability.getParam("Planeswalker"))
                    || !"True".equals(ability.getParam("UnlessSwitched"))
                    || !"You".equals(ability.getParam("UnlessPayer"))
                    || sacrifice.payCostFromSource()
                    || !"1".equals(sacrifice.getAmount())
                    || sacrifice.getTypeDescription() != null
                    || loyalty == null
                    || !loyalty.payCostFromSource()
                    || !"CARDNAME".equals(loyalty.getType())
                    || loyalty.counter == null
                    || !"Loyalty".equals(loyalty.counter.getName())) return false;
            if ("Garruk Relentless".equals(name)) {
                return "Garruk, the Veil-Cursed".equals(source.getName())
                        && ability.getApi() == ApiType.ChangeZone
                        && ability.getSubAbility() == null
                        && !ability.usesTargeting()
                        && "1".equals(loyalty.getAmount())
                        && "Sac<1/Creature>".equals(ability.getParam("UnlessCost"))
                        && "Creature".equals(sacrifice.getType())
                        && "Library".equals(ability.getParam("Origin"))
                        && "Hand".equals(ability.getParam("Destination"))
                        && "Creature".equals(ability.getParam("ChangeType"))
                        && "1".equals(ability.getParam("ChangeNum"));
            }
            if ("Daretti, Ingenious Iconoclast".equals(name)) {
                TargetRestrictions targets = ability.getTargetRestrictions();
                return ability.getApi() == ApiType.Destroy
                        && ability.getSubAbility() == null
                        && "1".equals(loyalty.getAmount())
                        && "Sac<1/Artifact>".equals(ability.getParam("UnlessCost"))
                        && "Artifact".equals(sacrifice.getType())
                        && targets != null
                        && ability.getMinTargets() == 1
                        && ability.getMaxTargets() == 1
                        && !targets.isRandomTarget()
                        && targets.getZone().size() == 1
                        && targets.getZone().contains(ZoneType.Battlefield)
                        && "Artifact,Creature".equals(ability.getParam("ValidTgts"));
            }
            if (!"Grist, the Hunger Tide".equals(name)
                    || ability.getApi() != ApiType.ImmediateTrigger
                    || ability.getSubAbility() != null
                    || !"2".equals(loyalty.getAmount())
                    || !"Sac<1/Creature>".equals(ability.getParam("UnlessCost"))
                    || !"Creature".equals(sacrifice.getType())
                    || !ability.hasAdditionalAbility("Execute")) return false;
            SpellAbility execute = ability.getAdditionalAbility("Execute");
            TargetRestrictions targets = execute.getTargetRestrictions();
            return execute.getHostCard() == source
                    && execute.getApi() == ApiType.Destroy
                    && execute.getRootAbility() == ability
                    && execute.getSubAbility() == null
                    && "Creature,Planeswalker".equals(execute.getParam("ValidTgts"))
                    && targets != null
                    && execute.getMinTargets() == 1
                    && execute.getMaxTargets() == 1
                    && !targets.isRandomTarget()
                    && targets.getZone().size() == 1
                    && targets.getZone().contains(ZoneType.Battlefield);
        }

