        private static boolean isReviewedRecurringNightmareAbility(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            TargetRestrictions targets = ability.getTargetRestrictions();
            if (source == null
                    || !"Recurring Nightmare".equals(source.getName())
                    || !ability.isActivatedAbility()
                    || ability.getParent() != null
                    || ability.getSubAbility() != null
                    || ability.getApi() != ApiType.ChangeZone
                    || !"Creature.YouCtrl".equals(ability.getParam("ValidTgts"))
                    || !"Graveyard".equals(ability.getParam("Origin"))
                    || !"Battlefield".equals(ability.getParam("Destination"))
                    || !"True".equals(ability.getParam("SorcerySpeed"))
                    || !"SacAndRetFromGrave".equals(ability.getParam("AILogic"))
                    || targets == null
                    || ability.getMinTargets() != 1
                    || ability.getMaxTargets() != 1
                    || targets.getZone().size() != 1
                    || !targets.getZone().contains(ZoneType.Graveyard)
                    || parts.size() != 2) return false;
            CostSacrifice sacrifice = null;
            CostReturn returned = null;
            for (CostPart part : parts) {
                if (part.getClass() == CostSacrifice.class) sacrifice = (CostSacrifice) part;
                else if (part.getClass() == CostReturn.class) returned = (CostReturn) part;
                else return false;
            }
            return sacrifice != null
                    && !sacrifice.payCostFromSource()
                    && "1".equals(sacrifice.getAmount())
                    && "Creature".equals(sacrifice.getType())
                    && sacrifice.getTypeDescription() == null
                    && returned != null
                    && returned.payCostFromSource()
                    && "1".equals(returned.getAmount())
                    && "CARDNAME".equals(returned.getType())
                    && returned.getTypeDescription() == null;
        }

