        private static boolean isReviewedCryptbreakerTokenAbility(SpellAbility ability) {
            if (ability == null) return false;
            Card source = ability.getHostCard();
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            if (source == null
                    || !"Cryptbreaker".equals(source.getName())
                    || !source.isCreature()
                    || !source.getType().hasSubtype("Zombie")
                    || !ability.isActivatedAbility()
                    || ability.isSpell()
                    || ability.isTrigger()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || ability.getSubAbility() != null
                    || ability.getApi() != ApiType.Token
                    || ability.getTargetRestrictions() != null
                    || ability.usesTargeting()
                    || !"b_2_2_zombie".equals(ability.getParam("TokenScript"))
                    || !"You".equals(ability.getParam("TokenOwner"))
                    || parts.size() != 3
                    // Forge normalizes the source tap ahead of the mana part,
                    // even though the script spells Cost$ 1 B T ... . Pin the
                    // installed ability shape rather than the source order.
                    || parts.get(0).getClass() != CostTap.class
                    || parts.get(1).getClass() != CostPartMana.class
                    || !"{1}{B}".equals(((CostPartMana) parts.get(1)).getMana().getSimpleString())
                    || parts.get(2).getClass() != CostDiscard.class) return false;
            CostDiscard discard = (CostDiscard) parts.get(2);
            return !discard.payCostFromSource()
                    && "1".equals(discard.getAmount())
                    && "Card".equals(discard.getType())
                    && discard.getTypeDescription() == null;
        }

        private static String describeCryptbreakerAbility(SpellAbility ability) {
            if (ability == null) return "ability=null";
            Card source = ability.getHostCard();
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            SpellAbility selected = ability.getSubAbility();
            return "source=" + (source == null ? "null" : source.getName())
                    + ", creature=" + (source != null && source.isCreature())
                    + ", type=" + (source == null ? "null" : source.getType())
                    + ", activated=" + ability.isActivatedAbility()
                    + ", spell=" + ability.isSpell()
                    + ", trigger=" + ability.isTrigger()
                    + ", parent=" + ability.getParent()
                    + ", rootSame=" + (ability.getRootAbility() == ability)
                    + ", api=" + ability.getApi()
                    + ", targets=" + ability.getTargetRestrictions()
                    + ", usesTargeting=" + ability.usesTargeting()
                    + ", params=" + ability.getMapParams()
                    + ", costParts=" + parts.stream().map(part -> part.getClass().getSimpleName()).toList()
                    + ", costs=" + parts
                    + ", sub=" + selected
                    + (selected == null
                            ? ""
                            : ", subParentSame=" + (selected.getParent() == ability)
                                    + ", subRootSame=" + (selected.getRootAbility() == ability)
                                    + ", subApi=" + selected.getApi()
                                    + ", subParams=" + selected.getMapParams());
        }

