        private static boolean isReviewedUroEffectTrigger(Trigger trigger, Card source) {
            if (trigger == null
                    || source == null
                    || trigger.getHostCard() != source
                    || !trigger.isIntrinsic()
                    || !"Card.Self".equals(trigger.getParam("ValidCard"))
                    || !"TrigGainLife".equals(trigger.getParam("Execute"))
                    || !"When NICKNAME enters or attacks, you gain 3 life and draw a card, then you may put a land card from your hand onto the battlefield."
                            .equals(trigger.getParam("TriggerDescription"))) return false;
            if (trigger.getMode() == TriggerType.ChangesZone) {
                return "Any".equals(trigger.getParam("Origin"))
                        && "Battlefield".equals(trigger.getParam("Destination"))
                        && !trigger.hasParam("OptionalDecider")
                        && !trigger.hasParam("Secondary")
                        && trigger.getMapParams().size() == 6;
            }
            if (trigger.getMode() == TriggerType.Attacks) {
                return "Battlefield".equals(trigger.getParam("TriggerZones"))
                        && "You".equals(trigger.getParam("OptionalDecider"))
                        && "True".equals(trigger.getParam("Secondary"))
                        && trigger.getMapParams().size() == 7;
            }
            return false;
        }

