        private static boolean isReviewedUroEffectAbility(SpellAbility gain) {
            SpellAbility presentedGain = gain;
            gain = reviewedUroTriggeredAbility(gain);
            if (gain == null) return false;
            Card source = gain.getHostCard();
            SpellAbility draw = gain.getSubAbility();
            SpellAbility land = draw == null ? null : draw.getSubAbility();
            return source != null
                    && "Uro, Titan of Nature's Wrath".equals(source.getName())
                    && gain.getApi() == ApiType.GainLife
                    && gain.isTrigger()
                    && !gain.isSpell()
                    && !gain.isActivatedAbility()
                    && gain.getParent() == null
                    && gain.getRootAbility() == gain
                    && gain.getTargetRestrictions() == null
                    && !gain.usesTargeting()
                    && "3".equals(gain.getParam("LifeAmount"))
                    && "DBDraw".equals(gain.getParam("SubAbility"))
                    && draw != null
                    && draw.getHostCard() == source
                    && (draw.getParent() == gain || draw.getParent() == presentedGain)
                    && draw.getApi() == ApiType.Draw
                    && "You".equals(draw.getParam("Defined"))
                    && "DBLand".equals(draw.getParam("SubAbility"))
                    && land != null
                    && land.getHostCard() == source
                    && land.getParent() == draw
                    && land.getApi() == ApiType.ChangeZone
                    && land.getSubAbility() == null
                    && "Hand".equals(land.getParam("Origin"))
                    && "Battlefield".equals(land.getParam("Destination"))
                    && "Land".equals(land.getParam("ChangeType"))
                    && "1".equals(land.getParam("ChangeNum"))
                    && isReviewedUroEffectTrigger(gain.getTrigger(), source);
        }

        private static SpellAbility reviewedUroTriggeredAbility(SpellAbility presented) {
            if (!(presented instanceof WrappedAbility wrapper)) return presented;
            SpellAbility wrapped = wrapper.getWrappedAbility();
            if (wrapped == null
                    || wrapper.getHostCard() != wrapped.getHostCard()
                    || wrapper.getTrigger() != wrapped.getTrigger()) return null;
            return wrapped;
        }

        private static boolean isReviewedUroLandPlacement(
                SpellAbility ability, List<ZoneType> origin, ZoneType destination) {
            if (ability == null) return false;
            SpellAbility draw = ability.getParent();
            SpellAbility gain = draw == null ? null : draw.getParent();
            SpellAbility reviewedGain = reviewedUroTriggeredAbility(gain);
            return origin.equals(List.of(ZoneType.Hand))
                    && destination == ZoneType.Battlefield
                    && reviewedGain != null
                    && isReviewedUroEffectAbility(gain)
                    && reviewedGain.getSubAbility() == draw
                    && draw.getSubAbility() == ability;
        }

        private static String reviewedUroTriggerOrderLabel(SpellAbility ability) {
            if (isReviewedUroSacrificeAbility(ability)) {
                return "sacrifice-unless-escaped trigger next";
            }
            Trigger trigger = ability == null ? null : ability.getTrigger();
            if (isReviewedUroEffectAbility(ability)
                    && trigger != null
                    && trigger.getMode() == TriggerType.ChangesZone) {
                return "gain 3 life, draw a card, and optional land trigger next";
            }
            return null;
        }

        private static boolean isReviewedUroAttackTrigger(WrappedAbility wrapper) {
            if (wrapper == null) return false;
            SpellAbility wrapped = wrapper.getWrappedAbility();
            Trigger trigger = wrapper.getTrigger();
            return wrapped != null
                    && wrapper.getHostCard() == wrapped.getHostCard()
                    && trigger == wrapped.getTrigger()
                    && trigger != null
                    && trigger.getMode() == TriggerType.Attacks
                    && "True".equals(trigger.getParam("Secondary"))
                    && isReviewedUroEffectAbility(wrapper);
        }

