        private static boolean isReviewedFreeCounterspellHandExileCost(
                CostExile exile, SpellAbility ability) {
            Card source = ability.getHostCard();
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            TargetRestrictions targets = ability.getTargetRestrictions();
            if (source == null
                    || !ability.isSpell()
                    || ability.isActivatedAbility()
                    || ability.isTrigger()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || ability.getSubAbility() != null
                    || ability.getApi() != ApiType.Counter
                    || targets == null
                    || ability.getMinTargets() != 1
                    || ability.getMaxTargets() != 1
                    || targets.isRandomTarget()
                    || targets.getZone().size() != 1
                    || !targets.getZone().contains(ZoneType.Stack)
                    || !"Spell".equals(ability.getParam("TargetType"))
                    || ability.hasParam("UnlessCost")
                    || exile.payCostFromSource()
                    || !"1".equals(exile.getAmount())
                    || !"Card.Blue+Other".equals(exile.getType())
                    || exile.zoneRestriction != 1
                    || !exile.getFrom().equals(List.of(ZoneType.Hand))) return false;
            boolean forceOfNegation = "Force of Negation".equals(source.getName())
                    && "Card.nonCreature".equals(ability.getParam("ValidTgts"))
                    && "Exile".equals(ability.getParam("Destination"))
                    && parts.size() == 2
                    && parts.get(0).getClass() == CostPartMana.class
                    && "{0}".equals(((CostPartMana) parts.get(0)).getMana().getSimpleString())
                    && parts.get(1).getClass() == CostExile.class;
            boolean forceOfWill = "Force of Will".equals(source.getName())
                    && "Card".equals(ability.getParam("ValidTgts"))
                    && "Graveyard".equals(ability.getParam("Destination"))
                    && parts.size() == 3
                    && parts.get(0).getClass() == CostPartMana.class
                    && "{0}".equals(((CostPartMana) parts.get(0)).getMana().getSimpleString())
                    && parts.get(1).getClass() == CostPayLife.class
                    && "1".equals(parts.get(1).getAmount())
                    && parts.get(2).getClass() == CostExile.class;
            return forceOfNegation || forceOfWill;
        }

        private static String reviewedSourceName(Card source) {
            if (source == null || source.getOriginalState(CardStateName.Original) == null) return "";
            return source.getOriginalState(CardStateName.Original).getName();
        }

        private static boolean isReviewedForetellSource(Card source) {
            String name = reviewedSourceName(source);
            return "Starnheim Unleashed".equals(name) || "Alrund's Epiphany".equals(name);
        }

        private static boolean isReviewedForetellAbility(SpellAbility ability) {
            Card source = ability.getHostCard();
            String name = reviewedSourceName(source);
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            String mana = parts.size() == 1 && parts.get(0).getClass() == CostPartMana.class
                    ? ((CostPartMana) parts.get(0)).getMana().getSimpleString()
                    : "";
            if (source == null
                    || !isReviewedForetellSource(source)
                    || ability.isActivatedAbility()
                    || ability.isTrigger()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || ability.getTargetRestrictions() != null
                    || !ability.isIntrinsic()) return false;

            if (ability.isForetelling()) {
                return !ability.isSpell()
                        && !ability.isForetold()
                        && ability.getApi() == null
                        && ability.getSubAbility() == null
                        && source.isInZone(ZoneType.Hand)
                        && ability.getRestrictions().getZone() == ZoneType.Hand
                        && "{2}".equals(mana)
                        && ability.getMapParams().size() == 1
                        && "True".equals(ability.getParam("Secondary"));
            }

            if (!ability.isForetold()
                    || ability.isForetelling()
                    || !ability.isSpell()
                    || ability.getApi() != ApiType.Token
                    || !source.isInZone(ZoneType.Exile)
                    || !source.isFaceDown()
                    || !source.isForetold()
                    || source.enteredThisTurn()
                    || source.getOwner() != ability.getActivatingPlayer()
                    || ability.getRestrictions().getZone() != ZoneType.Exile
                    || !"(Foretold)".equals(ability.getParam("AfterDescription"))) return false;

            if ("Starnheim Unleashed".equals(name)) {
                return "{X}{X}{W}".equals(mana)
                        && "Y".equals(ability.getParam("TokenAmount"))
                        && "w_4_4_angel_warrior_flying_vigilance".equals(ability.getParam("TokenScript"))
                        && !ability.hasParam("TokenOwner")
                        && ability.getSubAbility() == null;
            }

            AbilitySub addTurn = ability.getSubAbility();
            AbilitySub exile = addTurn == null ? null : addTurn.getSubAbility();
            return "Alrund's Epiphany".equals(name)
                    && "{4}{U}{U}".equals(mana)
                    && "2".equals(ability.getParam("TokenAmount"))
                    && "u_1_1_bird_flying".equals(ability.getParam("TokenScript"))
                    && "You".equals(ability.getParam("TokenOwner"))
                    && addTurn != null
                    && addTurn.getParent() == ability
                    && addTurn.getRootAbility() == ability
                    && addTurn.getApi() == ApiType.AddTurn
                    && "You".equals(addTurn.getParam("Defined"))
                    && "1".equals(addTurn.getParam("NumTurns"))
                    && exile != null
                    && exile.getParent() == addTurn
                    && exile.getRootAbility() == ability
                    && exile.getApi() == ApiType.ChangeZone
                    && "Stack".equals(exile.getParam("Origin"))
                    && "Exile".equals(exile.getParam("Destination"))
                    && exile.getSubAbility() == null;
        }

        private static boolean isReviewedFreeCounterspellAlternativeAbility(SpellAbility ability) {
            if (!ability.isOptionalCostPaid(OptionalCost.AltCost)) return false;
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            if (parts.size() == 2 && parts.get(1).getClass() == CostExile.class) {
                return isReviewedFreeCounterspellHandExileCost((CostExile) parts.get(1), ability);
            }
            if (parts.size() == 3 && parts.get(2).getClass() == CostExile.class) {
                return isReviewedFreeCounterspellHandExileCost((CostExile) parts.get(2), ability);
            }
            return parts.size() == 2
                    && parts.get(1).getClass() == CostReturn.class
                    && isReviewedDazeReturnCost((CostReturn) parts.get(1), ability);
        }

        private static boolean isReviewedFreeCounterspellFlashbackAbility(SpellAbility ability) {
            Card source = ability.getHostCard();
            Cost payCosts = ability.getPayCosts();
            List<CostPart> parts = payCosts == null ? List.of() : payCosts.getCostParts();
            TargetRestrictions targets = ability.getTargetRestrictions();
            if (source == null
                    || !ability.isSpell()
                    || ability.isActivatedAbility()
                    || ability.isTrigger()
                    || ability.getParent() != null
                    || ability.getRootAbility() != ability
                    || ability.getSubAbility() != null
                    || ability.getApi() != ApiType.Counter
                    || !ability.isFlashback()
                    || !ability.isAlternativeCost(AlternativeCost.Flashback)
                    || ability.getOptionalCosts().iterator().hasNext()
                    || ability.getRestrictions().getZone() != ZoneType.Graveyard
                    || targets == null
                    || ability.getMinTargets() != 1
                    || ability.getMaxTargets() != 1
                    || targets.isRandomTarget()
                    || targets.getZone().size() != 1
                    || !targets.getZone().contains(ZoneType.Stack)
                    || !"Spell".equals(ability.getParam("TargetType"))
                    || parts.size() != 1
                    || parts.get(0).getClass() != CostPartMana.class) return false;

            String name = source.getName();
            String mana = ((CostPartMana) parts.get(0)).getMana().getSimpleString();
            if ("Daze".equals(name)) {
                return "{1}{U}".equals(mana)
                        && "Card".equals(ability.getParam("ValidTgts"))
                        && "1".equals(ability.getParam("UnlessCost"))
                        && !ability.hasParam("Destination")
                        && ability.getMapParams().equals(Map.of(
                                "SP", "Counter",
                                "TargetType", "Spell",
                                "TgtPrompt", "Select target spell",
                                "ValidTgts", "Card",
                                "UnlessCost", "1",
                                "AILogic", "MinCMC.4",
                                "SpellDescription", "Counter target spell unless its controller pays {1}."));
            }
            if ("Force of Negation".equals(name)) {
                return "{1}{U}{U}".equals(mana)
                        && "Card.nonCreature".equals(ability.getParam("ValidTgts"))
                        && !ability.hasParam("UnlessCost")
                        && "Exile".equals(ability.getParam("Destination"))
                        && ability.getMapParams().equals(Map.of(
                                "SP", "Counter",
                                "TargetType", "Spell",
                                "TgtPrompt", "Select target noncreature spell",
                                "ValidTgts", "Card.nonCreature",
                                "Destination", "Exile",
                                "StackDescription", "SpellDescription",
                                "SpellDescription", "Counter target noncreature spell. If that spell is countered this way, exile it instead of putting it into its owner's graveyard."));
            }
            return "Force of Will".equals(name)
                    && "{3}{U}{U}".equals(mana)
                    && "Card".equals(ability.getParam("ValidTgts"))
                    && !ability.hasParam("UnlessCost")
                    && "Graveyard".equals(ability.getParam("Destination"))
                    && ability.getMapParams().equals(Map.of(
                            "SP", "Counter",
                            "TargetType", "Spell",
                            "TgtPrompt", "Select target spell",
                            "ValidTgts", "Card",
                            "Destination", "Graveyard",
                            "AILogic", "MinCMC.3",
                            "SpellDescription", "Counter target spell."));
        }

