        private static boolean isReviewedFixedCyclingMana(CostPartMana part) {
            ManaCost mana = part.getMana();
            if (mana.isNoCost() || mana.isZero()) return false;
            for (ManaCostShard shard : mana) {
                if (!Set.of(ManaCostShard.WHITE, ManaCostShard.BLUE, ManaCostShard.BLACK,
                        ManaCostShard.RED, ManaCostShard.GREEN, ManaCostShard.COLORLESS,
                        ManaCostShard.GENERIC).contains(shard)) return false;
            }
            return true;
        }

